const files = {
 "src/app/studio/cards/page.tsx": "\"use client\";\n\n// Admin → Card maker. Send anything (text, a PDF, a photo, a link, an audio or video with notes) and the\n// AI turns it into one \"do this\" card in the Discover format: photo, hook, what you need, steps, the secret.\n// Staff check it in a real phone preview, fix any words, then publish. Men see it at the top of Discover.\n\nimport { CIRCLE_LABEL } from \"@/lib/content/circles\";\nimport { useMemo, useState } from \"react\";\nimport Link from \"next/link\";\nimport { CheckCircle2, FileUp, Link2, Loader2, Plus, Sparkles, Trash2, Type } from \"lucide-react\";\nimport { useStudio } from \"@/components/admin/AdminShell\";\nimport { Badge, ErrorBox, PageHeader, Panel, Segmented, btn, input } from \"@/components/admin/ui\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { ActionPost } from \"@/components/social/ActionFeed\";\nimport { LangOverride } from \"@/lib/i18n\";\nimport { getSupabase } from \"@/lib/supabase/client\";\nimport { getContentRepo } from \"@/lib/content/repo\";\nimport { ACTION_RESULTS, ACTION_TYPES, CHALLENGE_IDS } from \"@/lib/content/action-shape\";\nimport { CARD_PHOTOS, photoUrl, type CardPhoto } from \"@/lib/content/card-photos\";\nimport { newCardId, studioCardToItem, type StudioCard } from \"@/lib/content/studio-card\";\nimport { checkClaims } from \"@/lib/studio/claims\";\nimport type { CardDraft } from \"@/lib/ai/card\";\nimport type { ActionResult, ActionSlide, ActionType, ChallengeId } from \"@/lib/content/types\";\n\ntype Mode = \"text\" | \"file\" | \"link\";\ntype FileKind = \"pdf\" | \"image\" | \"audio\" | \"video\" | \"textfile\";\n\nconst MAX_SEND = 4 * 1024 * 1024;\n// The same names men see on Discover (Step 80)\nconst CHALLENGE_NAME: Record<ChallengeId, string> = CIRCLE_LABEL;\nconst RESULT_NAME: Record<ActionResult, string> = { tonight: \"Works tonight\", days: \"Results in days\", weeks2: \"1–3 weeks\", weeks4: \"3–6 weeks\", daily: \"Daily habit\" };\n\nfunction kindOf(f: File): FileKind | null {\n  if (f.type === \"application/pdf\" || /\\.pdf$/i.test(f.name)) return \"pdf\";\n  if (/^image\\/(jpeg|png|webp)$/.test(f.type)) return \"image\";\n  if (f.type.startsWith(\"audio/\")) return \"audio\";\n  if (f.type.startsWith(\"video/\")) return \"video\";\n  if (f.type.startsWith(\"text/\") || /\\.(txt|md)$/i.test(f.name)) return \"textfile\";\n  return null;\n}\n\nconst toBase64 = (f: File) =>\n  new Promise<string>((resolve, reject) => {\n    const r = new FileReader();\n    r.onload = () => resolve(String(r.result).split(\",\")[1] ?? \"\");\n    r.onerror = () => reject(new Error(\"Couldn't read the file.\"));\n    r.readAsDataURL(f);\n  });\n\nasync function askAi(body: Record<string, unknown>): Promise<CardDraft> {\n  const { data } = (await getSupabase()?.auth.getSession()) ?? { data: { session: null } };\n  const res = await fetch(\"/api/ai/card\", {\n    method: \"POST\",\n    headers: { \"content-type\": \"application/json\", authorization: `Bearer ${data.session?.access_token ?? \"\"}` },\n    body: JSON.stringify(body),\n  });\n  const json = await res.json().catch(() => ({ error: res.status === 413 ? \"That file is too big. Keep it under 4 MB.\" : `Server error (${res.status})` }));\n  if (!res.ok) throw new Error(json.error ?? `Server error (${res.status})`);\n  return json.card as CardDraft;\n}\n\nexport default function CardMakerPage() {\n  const studio = useStudio();\n  const showToast = useToast();\n  const [mode, setMode] = useState<Mode>(\"text\");\n  const [text, setText] = useState(\"\");\n  const [url, setUrl] = useState(\"\");\n  const [file, setFile] = useState<File | null>(null);\n  const [notes, setNotes] = useState(\"\");\n  const [useAsPhoto, setUseAsPhoto] = useState(true);\n  const [busy, setBusy] = useState<\"make\" | \"save\" | \"publish\" | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [card, setCard] = useState<StudioCard | null>(null);\n  const [lang, setLang] = useState<\"en\" | \"sw\">(\"sw\");\n  const [published, setPublished] = useState<string | null>(null);\n  const fk = file ? kindOf(file) : null;\n  const canPublish = studio.can(\"content.publish\");\n  const repo = getContentRepo();\n\n  async function make() {\n    setError(null);\n    setPublished(null);\n    setBusy(\"make\");\n    try {\n      let body: Record<string, unknown>;\n      let media: { videoUrl?: string; audioUrl?: string } = {};\n      const id = card?.id ?? newCardId(\"draft\");\n      if (mode === \"text\") body = { kind: \"text\", text, notes };\n      else if (mode === \"link\") body = { kind: \"link\", url, notes };\n      else {\n        if (!file || !fk) throw new Error(\"Choose a PDF, photo, audio, video or text file.\");\n        if (fk === \"textfile\") body = { kind: \"text\", text: await file.text(), notes };\n        else if (fk === \"audio\" || fk === \"video\") {\n          if (notes.trim().length < 20) throw new Error(`The AI can't listen to ${fk} yet. Write what it says (or paste a transcript) in the notes box.`);\n          const link = fk === \"audio\" ? await repo.uploadAudio(file, id) : await repo.uploadVideo(file, id);\n          media = fk === \"audio\" ? { audioUrl: link } : { videoUrl: link };\n          body = { kind: fk, name: file.name, notes };\n        } else {\n          if (file.size > MAX_SEND) throw new Error(\"Keep PDFs and photos under 4 MB.\");\n          body = { kind: fk, base64: await toBase64(file), mediaType: file.type, name: file.name, notes };\n        }\n      }\n      const d = await askAi(body);\n      let imageUrl: string | undefined;\n      if (mode === \"file\" && fk === \"image\" && useAsPhoto && file) imageUrl = await repo.uploadImage(file, id).catch(() => undefined);\n      setCard({\n        id: newCardId(d.title),\n        title: d.title,\n        titleSw: d.titleSw,\n        summary: d.summary,\n        summarySw: d.summarySw,\n        minutes: d.minutes,\n        action: d.action,\n        photo: d.photo,\n        imageUrl,\n        ...media,\n        sourceNote: mode === \"link\" ? `From ${url}` : mode === \"file\" && file ? `From file ${file.name}` : \"From pasted text\",\n      });\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  const item = useMemo(() => (card ? studioCardToItem(card) : null), [card]);\n  const blocks = useMemo(() => (item ? checkClaims(item).filter((i) => i.level === \"block\") : []), [item]);\n\n  async function save(publish: boolean) {\n    if (!item) return;\n    setError(null);\n    setBusy(publish ? \"publish\" : \"save\");\n    try {\n      // Publishing: goes live straight away (Step 66b: no professional-check gate)\n      await repo.save({ ...item, review: publish ? \"reviewed\" : \"draft\" }, publish ? \"published\" : \"draft\");\n      setPublished(publish ? \"published\" : \"draft\");\n      showToast(publish ? \"Published · men see it at the top of Discover\" : \"Saved as a draft in Content\");\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  const set = (patch: Partial<StudioCard>) => setCard((c) => (c ? { ...c, ...patch } : c));\n  const setAction = (patch: Partial<StudioCard[\"action\"]>) => setCard((c) => (c ? { ...c, action: { ...c.action, ...patch } } : c));\n  const setStep = (i: number, patch: Partial<ActionSlide>) =>\n    setCard((c) => (c ? { ...c, action: { ...c.action, steps: c.action.steps.map((s, k) => (k === i ? { ...s, ...patch } : s)) } } : c));\n\n  return (\n    <div className=\"space-y-5\">\n      <PageHeader\n        title=\"Card maker\"\n        sub=\"Send anything: text, a PDF, a photo, a link, or an audio or video with notes. The AI turns it into one “do this” card in the Discover format. Check it in the phone preview, fix any words, then publish.\"\n      />\n\n      <div className=\"grid gap-5 xl:grid-cols-[minmax(0,1fr)_420px]\">\n        <div className=\"space-y-5\">\n          <Panel title=\"1 · What are you sending?\">\n            <Segmented\n              label=\"Source\"\n              value={mode}\n              onChange={(m) => {\n                setMode(m);\n                setError(null);\n              }}\n              options={[\n                { id: \"text\", label: \"Text\" },\n                { id: \"file\", label: \"File\" },\n                { id: \"link\", label: \"Link\" },\n              ]}\n            />\n            <div className=\"mt-4 space-y-3\">\n              {mode === \"text\" && (\n                <label className=\"block text-sm\">\n                  <span className=\"mb-1 flex items-center gap-1.5 font-semibold\"><Type size={14} /> Paste the text</span>\n                  <textarea className={`${input} min-h-[180px]`} value={text} onChange={(e) => setText(e.target.value)} placeholder=\"An Instagram caption, a WhatsApp message, notes from a lesson, a recipe…\" />\n                </label>\n              )}\n              {mode === \"link\" && (\n                <label className=\"block text-sm\">\n                  <span className=\"mb-1 flex items-center gap-1.5 font-semibold\"><Link2 size={14} /> Link to a web page</span>\n                  <input className={input} value={url} onChange={(e) => setUrl(e.target.value)} placeholder=\"https://…\" inputMode=\"url\" />\n                  <span className=\"mt-1 block text-xs text-ink-soft\">Instagram, Facebook and TikTok hide posts from other servers: for those, paste the caption as Text or upload the photo.</span>\n                </label>\n              )}\n              {mode === \"file\" && (\n                <div className=\"text-sm\">\n                  <span className=\"mb-1 flex items-center gap-1.5 font-semibold\"><FileUp size={14} /> Upload a file</span>\n                  <input\n                    type=\"file\"\n                    accept=\".pdf,image/jpeg,image/png,image/webp,audio/*,video/*,.txt,.md\"\n                    onChange={(e) => {\n                      const f = e.target.files?.[0] ?? null;\n                      setFile(f);\n                      setError(f && !kindOf(f) ? (/\\.docx?$/i.test(f.name) ? \"Word files: save it as PDF first (File → Save as → PDF), then upload the PDF.\" : \"Use a PDF, photo (JPG, PNG, WebP), audio, video or .txt file.\") : null);\n                    }}\n                    className=\"block w-full text-sm file:mr-3 file:rounded-full file:border-0 file:bg-forest file:px-4 file:py-2 file:text-sm file:font-semibold file:text-white\"\n                  />\n                  {file && fk && (\n                    <p className=\"mt-2 flex flex-wrap items-center gap-2 text-xs text-ink-soft\">\n                      <Badge tone=\"info\">{fk === \"textfile\" ? \"Text file\" : fk.toUpperCase()}</Badge>\n                      {file.name} · {(file.size / 1024 / 1024).toFixed(1)} MB\n                      {(fk === \"pdf\" || fk === \"image\") && file.size > MAX_SEND && <Badge tone=\"bad\">Too big: keep it under 4 MB</Badge>}\n                    </p>\n                  )}\n                  {fk === \"image\" && (\n                    <label className=\"mt-2 flex items-center gap-2 text-xs\">\n                      <input type=\"checkbox\" checked={useAsPhoto} onChange={(e) => setUseAsPhoto(e.target.checked)} /> Use this photo as the card&apos;s background\n                    </label>\n                  )}\n                  {(fk === \"audio\" || fk === \"video\") && (\n                    <p className=\"mt-2 rounded-xl bg-amber-50 px-3 py-2 text-xs text-amber-900 dark:bg-amber-950/40 dark:text-amber-100\">\n                      The AI can&apos;t listen to {fk} yet. The file will play on the card; write what it says (or paste a transcript) in the notes below so the AI can write the steps.\n                    </p>\n                  )}\n                </div>\n              )}\n              <label className=\"block text-sm\">\n                <span className=\"mb-1 block font-semibold\">Notes for the AI {fk === \"audio\" || fk === \"video\" ? \"(needed)\" : \"(optional)\"}</span>\n                <textarea\n                  className={`${input} min-h-[80px]`}\n                  value={notes}\n                  onChange={(e) => setNotes(e.target.value)}\n                  placeholder={fk === \"audio\" || fk === \"video\" ? \"What does the audio/video teach? Write the steps or paste the transcript.\" : \"E.g. make it about lasting longer · use only the second recipe · for married men\"}\n                />\n              </label>\n              <button className={btn.primary} disabled={busy !== null || (mode === \"text\" && text.trim().length < 20) || (mode === \"link\" && !url.trim()) || (mode === \"file\" && !fk)} onClick={make}>\n                {busy === \"make\" ? <Loader2 size={16} className=\"animate-spin\" /> : <Sparkles size={16} />} {card ? \"Make it again\" : \"Make the card\"}\n              </button>\n            </div>\n          </Panel>\n\n          {error && <ErrorBox error={error} />}\n\n          {card && (\n            <Panel title=\"2 · Check the words\" sub=\"Fix anything that isn't right. The preview updates as you type.\">\n              <div className=\"space-y-4\">\n                <Pair label=\"Title\" en={card.title} sw={card.titleSw} onChange={(title, titleSw) => set({ title, titleSw })} />\n                <Pair label=\"Opening line\" en={card.summary} sw={card.summarySw} onChange={(summary, summarySw) => set({ summary, summarySw })} long />\n                <div className=\"grid gap-3 sm:grid-cols-3\">\n                  <label className=\"text-sm\">\n                    <span className=\"mb-1 block font-semibold\">Kind</span>\n                    <select className={input} value={card.action.type} onChange={(e) => setAction({ type: e.target.value as ActionType })}>\n                      {ACTION_TYPES.map((t) => <option key={t} value={t}>{t}</option>)}\n                    </select>\n                  </label>\n                  <label className=\"text-sm\">\n                    <span className=\"mb-1 block font-semibold\">When he feels it</span>\n                    <select className={input} value={card.action.results} onChange={(e) => setAction({ results: e.target.value as ActionResult })}>\n                      {ACTION_RESULTS.map((r) => <option key={r} value={r}>{RESULT_NAME[r]}</option>)}\n                    </select>\n                  </label>\n                  <label className=\"text-sm\">\n                    <span className=\"mb-1 block font-semibold\">Minutes</span>\n                    <input type=\"number\" min={1} max={30} className={input} value={card.minutes} onChange={(e) => set({ minutes: Math.min(30, Math.max(1, Number(e.target.value) || 1)) })} />\n                  </label>\n                </div>\n                <fieldset className=\"text-sm\">\n                  <legend className=\"mb-1 font-semibold\">Circle on Discover (what men tap at the top)</legend>\n                  <div className=\"flex flex-wrap gap-2\">\n                    {CHALLENGE_IDS.map((c) => {\n                      const on = card.action.challenges.includes(c);\n                      return (\n                        <button\n                          key={c}\n                          type=\"button\"\n                          onClick={() => {\n                            const next = on ? card.action.challenges.filter((x) => x !== c) : [...card.action.challenges, c];\n                            if (next.length) setAction({ challenges: next });\n                          }}\n                          className={`rounded-full px-3 py-1.5 text-xs font-semibold ring-1 ${on ? \"bg-forest text-white ring-forest\" : \"ring-line\"}`}\n                        >\n                          {CHALLENGE_NAME[c]}\n                        </button>\n                      );\n                    })}\n                  </div>\n                </fieldset>\n\n                {(card.action.need?.length ?? 0) > 0 && (\n                  <div className=\"space-y-2\">\n                    <p className=\"text-sm font-semibold\">You need</p>\n                    {card.action.need!.map((n, i) => (\n                      <Pair\n                        key={i}\n                        en={n}\n                        sw={card.action.needSw?.[i] ?? n}\n                        onChange={(en, sw) =>\n                          setAction({ need: card.action.need!.map((x, k) => (k === i ? en : x)), needSw: (card.action.needSw ?? card.action.need!).map((x, k) => (k === i ? sw : x)) })\n                        }\n                      />\n                    ))}\n                  </div>\n                )}\n\n                <div className=\"space-y-3\">\n                  <p className=\"text-sm font-semibold\">Steps</p>\n                  {card.action.steps.map((s, i) => (\n                    <div key={i} className=\"rounded-2xl p-3 ring-1 ring-line\">\n                      <div className=\"mb-2 flex items-center justify-between text-xs font-semibold text-ink-soft\">\n                        Step {i + 1}\n                        {card.action.steps.length > 1 && (\n                          <button className={btn.small} onClick={() => setAction({ steps: card.action.steps.filter((_, k) => k !== i) })}>\n                            <Trash2 size={12} /> Remove\n                          </button>\n                        )}\n                      </div>\n                      {(s.title || s.titleSw) && <Pair label=\"Step title\" en={s.title ?? \"\"} sw={s.titleSw ?? \"\"} onChange={(title, titleSw) => setStep(i, { title, titleSw })} />}\n                      <Pair en={s.text} sw={s.textSw} onChange={(text, textSw) => setStep(i, { text, textSw })} long />\n                    </div>\n                  ))}\n                  {card.action.steps.length < 12 && (\n                    <button className={btn.small} onClick={() => setAction({ steps: [...card.action.steps, { text: \"New step\", textSw: \"Hatua mpya\" }] })}>\n                      <Plus size={12} /> Add a step\n                    </button>\n                  )}\n                </div>\n                <Pair\n                  label=\"The secret (why it works)\"\n                  en={card.action.why ?? \"\"}\n                  sw={card.action.whySw ?? \"\"}\n                  onChange={(why, whySw) => setAction(why || whySw ? { why, whySw } : { why: undefined, whySw: undefined })}\n                  long\n                />\n\n                <div>\n                  <p className=\"mb-2 text-sm font-semibold\">Background photo</p>\n                  <div className=\"grid grid-cols-5 gap-2 sm:grid-cols-7\">\n                    {card.imageUrl && (\n                      <button onClick={() => set({ photo: null })} className={`overflow-hidden rounded-xl ring-2 ${card.photo === null ? \"ring-forest\" : \"ring-transparent\"}`} title=\"Your uploaded photo\">\n                        {/* eslint-disable-next-line @next/next/no-img-element */}\n                        <img src={card.imageUrl} alt=\"Uploaded\" className=\"aspect-square w-full object-cover\" />\n                      </button>\n                    )}\n                    {CARD_PHOTOS.map((p: CardPhoto) => (\n                      <button\n                        key={p}\n                        onClick={() => set({ photo: p, imageUrl: card.photo === null ? undefined : card.imageUrl })}\n                        className={`overflow-hidden rounded-xl ring-2 ${card.photo === p && !(card.imageUrl && card.photo === null) ? \"ring-forest\" : \"ring-transparent\"}`}\n                        title={p}\n                      >\n                        {/* eslint-disable-next-line @next/next/no-img-element */}\n                        <img src={photoUrl(p)} alt={p} loading=\"lazy\" className=\"aspect-square w-full object-cover\" />\n                      </button>\n                    ))}\n                  </div>\n                </div>\n              </div>\n            </Panel>\n          )}\n        </div>\n\n        {/* Phone preview and publish */}\n        <div className=\"space-y-4 xl:sticky xl:top-4 xl:self-start\">\n          {item ? (\n            <>\n              <div className=\"flex items-center justify-between\">\n                <p className=\"text-xs font-semibold uppercase tracking-wider text-ink-soft\">How men will see it</p>\n                <Segmented label=\"Preview language\" value={lang} onChange={setLang} options={[{ id: \"sw\", label: \"Kiswahili\" }, { id: \"en\", label: \"English\" }]} />\n              </div>\n              <div className=\"mx-auto max-w-[390px] rounded-[32px] bg-bg p-3 ring-1 ring-line\">\n                <LangOverride lang={lang}>\n                  <ActionPost card={{ item: { ...item, coverImageUrl: card!.photo === null && card!.imageUrl ? card!.imageUrl : card!.photo ? photoUrl(card!.photo) : item.coverImageUrl }, spec: item.action! }} first done={false} liked={false} saved={false} />\n                </LangOverride>\n              </div>\n              {blocks.length > 0 && (\n                <ErrorBox error={`Fix before publishing: ${blocks.map((b) => b.message).join(\" · \")}`} />\n              )}\n              <div className=\"flex flex-wrap gap-2\">\n                <button className={btn.ghost} disabled={busy !== null} onClick={() => save(false)}>\n                  {busy === \"save\" && <Loader2 size={15} className=\"animate-spin\" />} Save as draft\n                </button>\n                {canPublish ? (\n                  <button className={btn.primary} disabled={busy !== null || blocks.length > 0} onClick={() => save(true)}>\n                    {busy === \"publish\" ? <Loader2 size={15} className=\"animate-spin\" /> : <CheckCircle2 size={15} />} Publish\n                  </button>\n                ) : (\n                  <p className=\"text-xs text-ink-soft\">Your role can save drafts. An editor or owner publishes them from Content.</p>\n                )}\n              </div>\n              {published && (\n                <p className=\"text-sm text-forest\">\n                  {published === \"published\" ? \"Live. It's at the top of Discover now.\" : \"Saved. Find it in \"}\n                  {published !== \"published\" && <Link href=\"/studio/content\" className=\"font-semibold underline\">Content</Link>}\n                </p>\n              )}\n            </>\n          ) : (\n            <div className=\"rounded-3xl p-6 text-sm text-ink-soft ring-1 ring-dashed ring-line\">\n              The phone preview shows here after the AI makes the card.\n            </div>\n          )}\n        </div>\n      </div>\n    </div>\n  );\n}\n\nfunction Pair({ label, en, sw, onChange, long = false }: { label?: string; en: string; sw: string; onChange: (en: string, sw: string) => void; long?: boolean }) {\n  const Field = long ? \"textarea\" : \"input\";\n  return (\n    <div className=\"text-sm\">\n      {label && <p className=\"mb-1 font-semibold\">{label}</p>}\n      <div className=\"grid gap-2 sm:grid-cols-2\">\n        <Field className={`${input} ${long ? \"min-h-[64px]\" : \"\"}`} value={en} onChange={(e) => onChange(e.target.value, sw)} aria-label={`${label ?? \"Text\"} (English)`} placeholder=\"English\" />\n        <Field className={`${input} ${long ? \"min-h-[64px]\" : \"\"}`} value={sw} onChange={(e) => onChange(en, e.target.value)} aria-label={`${label ?? \"Text\"} (Kiswahili)`} placeholder=\"Kiswahili\" lang=\"sw\" />\n      </div>\n    </div>\n  );\n}\n",
 "src/app/studio/discover/page.tsx": "\"use client\";\n\n// Studio → Discover (Step 71). Matches what men see now on Social → Discover:\n//   reels inside the feed (full width, playing as he scrolls; Step 73) and the \"do this\" cards.\n// Here staff upload reels, pin or hide cards and reels, and set the mix:\n//   - one reel after every N cards (3–12),\n//   - let each man's habits move it (watchers a bit more reels, readers fewer; never more than 1 in 3),\n//   - a new card order every visit, different for each man.\n// Saved as app_settings \"discover_config\" (migration 0016); every change is in the audit log.\n// Replaces the old Homepage editor (Featured insight, For you, Explore topics…), which men no longer see.\n\nimport { CIRCLE_LABEL } from \"@/lib/content/circles\";\nimport { useEffect, useMemo, useState } from \"react\";\nimport Link from \"next/link\";\nimport { Eye, EyeOff, Pin, PinOff, RefreshCw, Search, Shuffle, Upload, Wand2 } from \"lucide-react\";\nimport { useStudio } from \"@/components/admin/AdminShell\";\nimport { Badge, Confirm, Empty, ErrorBox, Loading, PageHeader, Panel, btn, input, useLoad } from \"@/components/admin/ui\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { rpc, select } from \"@/lib/admin/api\";\nimport { actionOf } from \"@/lib/content/actions\";\nimport { DEFAULT_DISCOVER, normalizeDiscover, orderCards, orderReels, placeReels, REEL_EVERY_MAX, REEL_EVERY_MIN, reelEvery, type DiscoverConfig, type FeedCard } from \"@/lib/content/discover\";\nimport { isReel } from \"@/lib/content/reels\";\nimport { youtubeId, youtubeThumb } from \"@/lib/content/youtube\";\nimport type { ChallengeId, ContentItem } from \"@/lib/content/types\";\nimport { useLibrary } from \"@/lib/content/useLibrary\";\n\n// The same names men see on Discover (Step 80)\nconst CHALLENGE_LABEL: Record<ChallengeId, string> = CIRCLE_LABEL;\ntype Stats = Record<string, { views: number; completes: number; saves: number; yes: number; some: number; no: number }>;\nconst same = (a: unknown, b: unknown) => JSON.stringify(a) === JSON.stringify(b);\n\nexport default function DiscoverStudioPage() {\n  const studio = useStudio();\n  const showToast = useToast();\n  const { items, ready } = useLibrary();\n  const canEdit = studio.can(\"homepage.publish\");\n\n  const saved = useLoad(async () => {\n    const rows = await select<{ value: unknown }>(\"app_settings\", \"value\", (q) => q.eq(\"key\", \"discover_config\"));\n    return normalizeDiscover(rows[0]?.value ?? DEFAULT_DISCOVER);\n  }, []);\n  const [work, setWork] = useState<DiscoverConfig | null>(null);\n  useEffect(() => {\n    if (saved.data) setWork(saved.data);\n  }, [saved.data]);\n  const cfg = work ?? DEFAULT_DISCOVER;\n  const dirty = Boolean(saved.data && work && !same(saved.data, work));\n\n  const stats = useLoad<Stats | null>(async () => {\n    if (!studio.can(\"analytics.view\")) return null;\n    const from = new Date(Date.now() - 30 * 864e5).toISOString().slice(0, 10);\n    // \"*\" so it still works before migration 0017 adds the \"Did it help?\" counts\n    const rows = await select<{ content_id: string; views: number; completes: number; saves: number; helped_yes?: number; helped_some?: number; helped_no?: number }>(\n      \"content_stats_daily\",\n      \"*\",\n      (q) => q.gte(\"day\", from),\n    );\n    const s: Stats = {};\n    for (const r of rows) {\n      const t = (s[r.content_id] ??= { views: 0, completes: 0, saves: 0, yes: 0, some: 0, no: 0 });\n      t.views += r.views;\n      t.completes += r.completes;\n      t.saves += r.saves;\n      t.yes += r.helped_yes ?? 0;\n      t.some += r.helped_some ?? 0;\n      t.no += r.helped_no ?? 0;\n    }\n    return s;\n  }, [studio]);\n\n  const cards = useMemo<FeedCard[]>(() => items.flatMap((item) => (actionOf(item) && item.status !== \"archived\" ? [{ item, spec: actionOf(item)! }] : [])), [items]);\n  const reels = useMemo(() => items.filter(isReel), [items]);\n\n  const [busy, setBusy] = useState(false);\n  const [confirm, setConfirm] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n  const toggle = (key: \"pinned\" | \"hidden\", id: string) =>\n    setWork((w) => {\n      const c = w ?? DEFAULT_DISCOVER;\n      const has = c[key].includes(id);\n      const next = { ...c, [key]: has ? c[key].filter((x) => x !== id) : [...c[key], id] };\n      // Pinned and hidden can't both be true\n      const other = key === \"pinned\" ? \"hidden\" : \"pinned\";\n      if (!has) next[other] = next[other].filter((x) => x !== id);\n      return next;\n    });\n\n  async function save() {\n    setBusy(true);\n    setError(null);\n    try {\n      await rpc(\"settings_set\", { p_key: \"discover_config\", p_value: cfg });\n      showToast(\"Saved · men see it the next time they open Discover\");\n      setConfirm(false);\n      saved.reload();\n    } catch (e) {\n      const m = (e as Error).message;\n      setError(/unknown setting/i.test(m) ? \"The database doesn't know these settings yet. Run supabase/migrations/0016_discover_settings.sql in Supabase → SQL Editor, then save again.\" : m);\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  return (\n    <div className=\"space-y-5\">\n      <PageHeader\n        title=\"Discover\"\n        sub=\"What men see on Social → Discover: full-width reels between the cards, and the “do this” cards. Upload reels, pin or hide things, and set how often reels come.\"\n        actions={\n          <div className=\"flex flex-wrap gap-2\">\n            {studio.can(\"content.edit\") && (\n              <Link href=\"/studio/edit?place=reels\" className={btn.primary}>\n                <Upload size={15} /> Upload a reel\n              </Link>\n            )}\n            {studio.can(\"content.edit\") && (\n              <Link href=\"/studio/cards\" className={btn.ghost}>\n                <Wand2 size={15} /> Make a card\n              </Link>\n            )}\n          </div>\n        }\n      />\n\n      {saved.error && <ErrorBox error={saved.error} onRetry={saved.reload} />}\n      {error && <ErrorBox error={error} />}\n\n      <div className=\"grid grid-cols-1 gap-5 xl:grid-cols-[minmax(0,1fr)_380px]\">\n        <div className=\"space-y-5\">\n          <FeedSettings cfg={cfg} canEdit={canEdit} onChange={setWork} />\n          <ReelsPanel reels={reels} cfg={cfg} stats={stats.data} canEdit={canEdit} onToggle={toggle} />\n          <CardsPanel cards={cards} cfg={cfg} stats={stats.data} canEdit={canEdit} onToggle={toggle} />\n        </div>\n        <div className=\"space-y-5 xl:sticky xl:top-4 xl:self-start\">\n          <OrderPreview cards={cards} reels={reels} cfg={cfg} ready={ready} />\n          {canEdit && (\n            <div className=\"rounded-2xl bg-surface p-4 ring-1 ring-line\">\n              <p className=\"text-sm font-semibold\">{dirty ? \"You have changes that men don't see yet.\" : \"Everything here is live.\"}</p>\n              <div className=\"mt-3 flex gap-2\">\n                <button className={btn.primary} disabled={!dirty || busy} onClick={() => setConfirm(true)}>\n                  Save for everyone\n                </button>\n                <button className={btn.ghost} disabled={!dirty || busy} onClick={() => saved.data && setWork(saved.data)}>\n                  Undo changes\n                </button>\n              </div>\n            </div>\n          )}\n        </div>\n      </div>\n\n      <Confirm open={confirm} title=\"Save the Discover settings?\" confirmLabel=\"Save\" busy={busy} onClose={() => setConfirm(false)} onConfirm={save}>\n        Every man gets them the next time he opens Discover. The change is written in the audit log.\n      </Confirm>\n    </div>\n  );\n}\n\n/* ───────── The mix ───────── */\nfunction FeedSettings({ cfg, canEdit, onChange }: { cfg: DiscoverConfig; canEdit: boolean; onChange: (c: DiscoverConfig) => void }) {\n  const watcher = reelEvery(cfg, { reelViews: 80, reelFinished: 75, reelSkipped: 0, cardActions: 5 });\n  const reader = reelEvery(cfg, { reelViews: 10, reelFinished: 0, reelSkipped: 9, cardActions: 80 });\n  return (\n    <Panel title=\"Feed mix\" sub=\"How reels and cards are mixed on each man's Discover.\">\n      <div className=\"space-y-5\">\n        <label className=\"block\">\n          <span className=\"flex items-baseline justify-between text-sm font-semibold\">\n            <span>One reel after every</span>\n            <span className=\"tabular-nums\">{cfg.reelEvery} cards</span>\n          </span>\n          <input\n            type=\"range\"\n            min={REEL_EVERY_MIN}\n            max={REEL_EVERY_MAX}\n            value={cfg.reelEvery}\n            disabled={!canEdit}\n            onChange={(e) => onChange({ ...cfg, reelEvery: Number(e.target.value) })}\n            className=\"mt-2 w-full accent-forest\"\n          />\n          <span className=\"flex justify-between text-[0.6875rem] text-ink-soft\">\n            <span>More reels (every {REEL_EVERY_MIN})</span>\n            <span>More reading (every {REEL_EVERY_MAX})</span>\n          </span>\n        </label>\n        <Switch\n          on={cfg.adaptive}\n          disabled={!canEdit}\n          onChange={(v) => onChange({ ...cfg, adaptive: v })}\n          title=\"Adapt to each man\"\n          about={`The app notices if he finishes reels or mostly reads and does the cards, and moves the mix for him: a man who watches gets a reel about every ${watcher} cards, a man who reads about every ${reader}. Never more than one reel per 3 cards. It needs a few visits before it changes anything, and it only matters once you have many reels.`}\n        />\n        <Switch\n          on={cfg.shuffle}\n          disabled={!canEdit}\n          onChange={(v) => onChange({ ...cfg, shuffle: v })}\n          title=\"New order every visit\"\n          about=\"Cards and reels come in a different order each time he opens Discover, and differ from man to man. Cards he hasn't opened, topics he follows and challenges he found useful come earlier. Pinned items stay first; cards he already did go last. Off = the same order for everyone.\"\n        />\n      </div>\n    </Panel>\n  );\n}\n\nfunction Switch({ on, disabled, onChange, title, about }: { on: boolean; disabled: boolean; onChange: (v: boolean) => void; title: string; about: string }) {\n  return (\n    <div className=\"flex items-start justify-between gap-4\">\n      <span>\n        <span className=\"block text-sm font-semibold\">{title}</span>\n        <span className=\"mt-0.5 block text-xs text-ink-soft\">{about}</span>\n      </span>\n      <button\n        role=\"switch\"\n        aria-checked={on}\n        aria-label={title}\n        disabled={disabled}\n        onClick={() => onChange(!on)}\n        className={`relative h-7 w-12 shrink-0 rounded-full transition-colors disabled:opacity-50 ${on ? \"bg-forest\" : \"bg-line\"}`}\n      >\n        <span className={`absolute top-1 h-5 w-5 rounded-full bg-white shadow transition-transform ${on ? \"left-6\" : \"left-1\"}`} />\n      </button>\n    </div>\n  );\n}\n\n/* ───────── Pin / hide buttons ───────── */\nfunction PinHide({ id, cfg, canEdit, onToggle }: { id: string; cfg: DiscoverConfig; canEdit: boolean; onToggle: (k: \"pinned\" | \"hidden\", id: string) => void }) {\n  const pinned = cfg.pinned.includes(id);\n  const hidden = cfg.hidden.includes(id);\n  return (\n    <span className=\"flex shrink-0 gap-1\">\n      <button\n        className={`${btn.small} ${pinned ? \"bg-mint text-forest-deep\" : \"\"}`}\n        disabled={!canEdit}\n        onClick={() => onToggle(\"pinned\", id)}\n        title={pinned ? \"Unpin\" : \"Pin to the top of Discover\"}\n        aria-pressed={pinned}\n      >\n        {pinned ? <PinOff size={13} /> : <Pin size={13} />} {pinned ? \"Pinned\" : \"Pin\"}\n      </button>\n      <button className={`${btn.small} ${hidden ? \"bg-red-50 text-red-700\" : \"\"}`} disabled={!canEdit} onClick={() => onToggle(\"hidden\", id)} title={hidden ? \"Show again\" : \"Take off Discover\"} aria-pressed={hidden}>\n        {hidden ? <Eye size={13} /> : <EyeOff size={13} />} {hidden ? \"Hidden\" : \"Hide\"}\n      </button>\n    </span>\n  );\n}\n\nconst editHref = (c: ContentItem) => (c.builtIn ? `/social/c/${c.id}` : `/studio/edit?id=${encodeURIComponent(c.id)}`);\n\n/* ───────── Reels ───────── */\nfunction ReelsPanel({ reels, cfg, stats, canEdit, onToggle }: { reels: ContentItem[]; cfg: DiscoverConfig; stats: Stats | null | undefined; canEdit: boolean; onToggle: (k: \"pinned\" | \"hidden\", id: string) => void }) {\n  return (\n    <Panel\n      title={`Reels (${reels.length})`}\n      sub=\"Upright videos (9:16), best under 90 seconds. They show full width between the cards (the first one after the first card), play silently as he scrolls, and open full screen with sound. “Do this” cards that have a video show here too.\"\n    >\n      {reels.length === 0 ? (\n        <Empty title=\"No reels yet\" action={<Link href=\"/studio/edit?place=reels\" className={btn.primary}><Upload size={15} /> Upload your first reel</Link>}>\n          Film it upright on a phone, keep it short, and write the title and caption in English and Kiswahili.\n        </Empty>\n      ) : (\n        <ul className=\"grid grid-cols-2 gap-3 sm:grid-cols-3 lg:grid-cols-4\">\n          {reels.map((r) => {\n            const s = stats?.[r.id];\n            return (\n              <li key={r.id} className={`overflow-hidden rounded-2xl ring-1 ring-line ${cfg.hidden.includes(r.id) ? \"opacity-50\" : \"\"}`}>\n                <Link href={editHref(r)} className=\"relative block aspect-[9/16] bg-forest-deep\">\n                  {r.coverImageUrl ? (\n                    // eslint-disable-next-line @next/next/no-img-element\n                    <img src={r.coverImageUrl} alt=\"\" className=\"absolute inset-0 h-full w-full object-cover\" />\n                  ) : (\n                    youtubeId(r.videoUrl) ? (\n                    // eslint-disable-next-line @next/next/no-img-element\n                    <img src={youtubeThumb(youtubeId(r.videoUrl)!)} alt=\"\" className=\"absolute inset-0 h-full w-full object-cover\" />\n                  ) : (\n                    <video src={`${r.videoUrl}#t=0.5`} muted playsInline preload=\"metadata\" className=\"absolute inset-0 h-full w-full object-cover\" />\n                  )\n                  )}\n                  <span className=\"absolute inset-0 bg-gradient-to-t from-black/75 to-transparent\" />\n                  {cfg.pinned.includes(r.id) && <span className=\"absolute left-2 top-2\"><Badge tone=\"good\">Pinned</Badge></span>}\n                  <span className=\"absolute inset-x-2 bottom-2 line-clamp-3 text-xs font-semibold text-white\">{r.title}</span>\n                </Link>\n                <div className=\"space-y-2 p-2\">\n                  <p className=\"text-[0.6875rem] text-ink-soft\">{s ? `${s.views} views · ${s.views ? Math.round((s.completes / s.views) * 100) : 0}% finished · ${s.saves} saved` : \"No views yet (30 days)\"}</p>\n                  <PinHide id={r.id} cfg={cfg} canEdit={canEdit} onToggle={onToggle} />\n                </div>\n              </li>\n            );\n          })}\n        </ul>\n      )}\n    </Panel>\n  );\n}\n\n/* ───────── Cards ───────── */\nfunction CardsPanel({ cards, cfg, stats, canEdit, onToggle }: { cards: FeedCard[]; cfg: DiscoverConfig; stats: Stats | null | undefined; canEdit: boolean; onToggle: (k: \"pinned\" | \"hidden\", id: string) => void }) {\n  const [q, setQ] = useState(\"\");\n  const [ch, setCh] = useState<\"all\" | ChallengeId | \"pinned\" | \"hidden\" | \"studio\">(\"all\");\n  const shown = cards.filter((c) => {\n    if (ch === \"pinned\" && !cfg.pinned.includes(c.item.id)) return false;\n    if (ch === \"hidden\" && !cfg.hidden.includes(c.item.id)) return false;\n    if (ch === \"studio\" && c.item.builtIn) return false;\n    if (![\"all\", \"pinned\", \"hidden\", \"studio\"].includes(ch) && !c.spec.challenges.includes(ch as ChallengeId)) return false;\n    const s = q.trim().toLowerCase();\n    return !s || `${c.item.title} ${c.item.titleSw ?? \"\"}`.toLowerCase().includes(s);\n  });\n  return (\n    <Panel\n      title={`“Do this” cards (${cards.length})`}\n      sub=\"The cards men swipe through on Discover. New ones come from Card maker. Pin one to put it at the top for everyone; hide one to take it off Discover (it still opens from links, search and Saved).\"\n    >\n      <div className=\"mb-3 flex flex-wrap gap-2\">\n        <label className=\"flex min-w-48 flex-1 items-center gap-2 rounded-xl bg-bg px-3 ring-1 ring-line\">\n          <Search size={14} className=\"text-ink-soft\" />\n          <input value={q} onChange={(e) => setQ(e.target.value)} placeholder=\"Search cards\" aria-label=\"Search cards\" className=\"w-full bg-transparent py-2 text-sm outline-none\" />\n        </label>\n        <select value={ch} onChange={(e) => setCh(e.target.value as typeof ch)} className={`${input} w-auto`} aria-label=\"Filter\">\n          <option value=\"all\">All cards</option>\n          <option value=\"pinned\">Pinned</option>\n          <option value=\"hidden\">Hidden</option>\n          <option value=\"studio\">Made in the Studio</option>\n          {Object.entries(CHALLENGE_LABEL).map(([id, label]) => (\n            <option key={id} value={id}>\n              {label}\n            </option>\n          ))}\n        </select>\n      </div>\n      <ul className=\"divide-y divide-line\">\n        {shown.slice(0, 80).map((c) => {\n          const s = stats?.[c.item.id];\n          return (\n            <li key={c.item.id} className={`flex items-center gap-3 py-2.5 ${cfg.hidden.includes(c.item.id) ? \"opacity-50\" : \"\"}`}>\n              <div className=\"min-w-0 flex-1\">\n                <Link href={editHref(c.item)} className=\"block truncate text-sm font-semibold hover:underline\">\n                  {c.item.title}\n                </Link>\n                <p className=\"truncate text-[0.6875rem] text-ink-soft\">\n                  {c.spec.challenges.map((x) => CHALLENGE_LABEL[x]).join(\" · \")} · {c.item.builtIn ? \"built-in\" : \"Studio\"}\n                  {c.item.videoUrl ? \" · has video (also a reel)\" : \"\"}\n                  {s ? ` · ${s.views} views, ${s.completes} did it` : \"\"}\n                  {s && s.yes + s.some + s.no > 0 ? ` · helped: ${s.yes} yes, ${s.some} a little, ${s.no} no` : \"\"}\n                </p>\n              </div>\n              <PinHide id={c.item.id} cfg={cfg} canEdit={canEdit} onToggle={onToggle} />\n            </li>\n          );\n        })}\n        {shown.length === 0 && <li className=\"py-6 text-center text-sm text-ink-soft\">No cards match.</li>}\n        {shown.length > 80 && <li className=\"py-3 text-center text-xs text-ink-soft\">Showing 80 of {shown.length}. Search to find others.</li>}\n      </ul>\n    </Panel>\n  );\n}\n\n/* ───────── What a man sees first ───────── */\nfunction OrderPreview({ cards, reels, cfg, ready }: { cards: FeedCard[]; reels: ContentItem[]; cfg: DiscoverConfig; ready: boolean }) {\n  const [seed, setSeed] = useState(\"preview-1\");\n  const feed = useMemo(() => {\n    const ordered = orderCards(cards, seed, { interests: [], opened: {}, liked: {}, done: {} }, cfg);\n    const r = orderReels(reels, seed, {}, cfg);\n    const spots = placeReels(ordered.length, r, cfg.reelEvery);\n    const out: { kind: \"card\" | \"reel\"; item: ContentItem }[] = [];\n    ordered.slice(0, 18).forEach((c, i) => {\n      const reel = spots.get(i);\n      if (reel) out.push({ kind: \"reel\", item: reel });\n      out.push({ kind: \"card\", item: c.item });\n    });\n    return { list: out };\n  }, [cards, reels, cfg, seed]);\n  if (!ready) return <Loading />;\n  return (\n    <Panel\n      title=\"What a new man sees\"\n      sub=\"The top of Discover for one visit, with these settings. Every visit and every man gets a different order.\"\n      actions={\n        <button className={btn.small} onClick={() => setSeed(`preview-${Math.random().toString(36).slice(2, 7)}`)} title=\"Another visit\">\n          <Shuffle size={13} /> Another visit\n        </button>\n      }\n    >\n      <ol className=\"space-y-1.5 text-sm\">\n        {feed.list.map((x, i) => (\n          <li key={`${x.kind}-${x.item.id}-${i}`} className={`flex items-center gap-2 rounded-xl px-2.5 py-1.5 ${x.kind === \"reel\" ? \"bg-forest-deep text-white\" : \"bg-bg\"}`}>\n            <span className={`w-12 shrink-0 text-[0.625rem] font-bold uppercase tracking-wider ${x.kind === \"reel\" ? \"text-mint\" : \"text-ink-soft\"}`}>{x.kind === \"reel\" ? \"Reel\" : \"Card\"}</span>\n            <span className=\"min-w-0 flex-1 truncate\">{x.item.title}</span>\n            {cfg.pinned.includes(x.item.id) && <Pin size={12} className=\"shrink-0\" />}\n          </li>\n        ))}\n      </ol>\n      <p className=\"mt-3 flex items-center gap-1.5 text-[0.6875rem] text-ink-soft\">\n        <RefreshCw size={11} /> Late at night (22:00–05:00), reels stop after 3 with “that’s enough for tonight”; in the day after 15.\n      </p>\n    </Panel>\n  );\n}\n",
 "src/components/social/ActionFeed.tsx": "\"use client\";\n\n// Discover as a feed of things to DO, not things to read about.\n// Top: \"What are you dealing with?\" circles, like Instagram stories. Below: one endless column of\n// action cards. Each card is a carousel he swipes through: the hook, what he needs, the steps,\n// why it works. Then: \"Useful\", share, save, and \"I did it\".\n\nimport { CIRCLES, circlesOf } from \"@/lib/content/circles\";\nimport { haptic } from \"@/lib/motion/haptics\";\nimport { flyPoints } from \"@/lib/motion/flyPoints\";\nimport { Fragment, useCallback, useEffect, useMemo, useRef, useState } from \"react\";\nimport Link from \"next/link\";\nimport {\n  ArrowRight,\n  BatteryCharging,\n  Bookmark,\n  Brain,\n  Check,\n  ChevronLeft,\n  ChevronRight,\n  Dumbbell,\n  Flame,\n  Hand,\n  Heart,\n  Leaf,\n  MessageCircle,\n  Moon,\n  Send,\n  Sparkles,\n  Timer,\n  Zap,\n} from \"lucide-react\";\nimport Cover from \"./Cover\";\nimport { contentHref } from \"./ContentCards\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { useLibrary } from \"@/lib/content/useLibrary\";\nimport { actionOf } from \"@/lib/content/actions\";\nimport type { ActionResult, ActionSpec, ActionType, ChallengeId, ContentItem } from \"@/lib/content/types\";\nimport { socialStore, useSocial } from \"@/lib/social/store\";\nimport { TRIED_POINTS, triedStore, useTried, type FeedFilter } from \"@/lib/social/tried\";\nimport { helpedYes } from \"@/lib/social/helped\";\nimport { useFeed } from \"@/lib/feed/store\";\nimport HelpedCheck from \"./HelpedCheck\";\nimport { trackContent } from \"@/lib/analytics/track\";\nimport { youtubeId } from \"@/lib/content/youtube\";\nimport { YouTubeFrame } from \"@/components/media/YouTubeFrame\";\nimport { inviteToAccount } from \"@/components/account/AccountInvite\";\nimport { useT, type T } from \"@/lib/i18n\";\nimport { ReelPost, ReelsViewer } from \"./Reels\";\nimport { openKito } from \"@/components/kito/KitoLauncher\";\nimport KitoMark from \"@/components/kito/KitoMark\";\nimport { isReel } from \"@/lib/content/reels\";\nimport { orderCards, orderReels, placeReels, reelEvery, type Habits } from \"@/lib/content/discover\";\nimport { DISCOVER_REFRESH, habitsStore, useDiscoverConfig, visitSeed } from \"@/lib/social/discoverPrefs\";\nimport { useAccount } from \"@/lib/account/useAccount\";\n\n// The circles: names from the shared list (lib/content/circles.ts), so the Studio uses the very same ones (Step 80)\nconst ICON: Record<ChallengeId, typeof Timer> = { last: Timer, hard: Zap, her: Flame, mixes: Leaf, train: Dumbbell, reset: Brain, desire: BatteryCharging };\nconst CHALLENGES: { id: FeedFilter; label: string; icon: typeof Timer }[] = [\n  { id: \"all\", label: \"For you\", icon: Sparkles },\n  ...CIRCLES.map((c) => ({ id: c.id, label: c.label, icon: ICON[c.id] })),\n];\n\nconst TYPE_LABEL: Record<ActionType, string> = {\n  technique: \"Technique\",\n  position: \"Positions\",\n  mix: \"Natural mix\",\n  exercise: \"Exercise\",\n  food: \"Food\",\n  habit: \"Daily habit\",\n  mind: \"Mindset\",\n};\n\nconst RESULT_LABEL: Record<ActionResult, string> = {\n  tonight: \"Works tonight\",\n  days: \"Results in days\",\n  weeks2: \"Feel it in 1–3 weeks\",\n  weeks4: \"Feel it in 3–6 weeks\",\n  daily: \"Daily habit\",\n};\n\nconst TYPE_ICON: Record<ActionType, typeof Timer> = {\n  technique: Flame,\n  position: Heart,\n  mix: Leaf,\n  exercise: Dumbbell,\n  food: Leaf,\n  habit: Moon,\n  mind: Brain,\n};\n\nconst PAGE = 8;\nconst TIMER_ID = \"tool-pelvic-floor\";\n\ntype Card = { item: ContentItem; spec: ActionSpec };\n\nexport function ActionFeedSkeleton() {\n  const t = useT();\n  return (\n    <div className=\"space-y-5\" aria-busy=\"true\" aria-label={t(\"Loading\")}>\n      <div className=\"flex gap-4 overflow-hidden\">\n        {[0, 1, 2, 3, 4].map((i) => (\n          <div key={i} className=\"h-[68px] w-[68px] shrink-0 animate-pulse rounded-full bg-line\" />\n        ))}\n      </div>\n      <div className=\"-mx-3 aspect-[5/4] animate-pulse rounded-[20px] bg-forest-deep/15 lg:mx-0\" />\n    </div>\n  );\n}\n\nexport default function ActionFeed() {\n  const { items } = useLibrary();\n  const feed = useFeed();\n  const tried = useTried();\n  const social = useSocial();\n  const t = useT();\n  const [shown, setShown] = useState(PAGE);\n  // Reels (Step 70): the order is fixed when the viewer opens, so it doesn't move while he watches\n  const [viewer, setViewer] = useState<{ list: ContentItem[]; start: number; sound: boolean } | null>(null);\n  const top = useRef<HTMLDivElement>(null);\n  const filter = tried.filter;\n\n  const acc = useAccount();\n  const cfg = useDiscoverConfig();\n  const accountId = acc.status === \"signedIn\" ? acc.user.id : null;\n\n  // Every \"do this\" card (built-in and from the Studio's Card maker)\n  const all = useMemo<Card[]>(\n    () =>\n      items.flatMap((item) => {\n        const spec = actionOf(item);\n        return spec && item.status !== \"archived\" ? [{ item, spec }] : [];\n      }),\n    [items],\n  );\n\n  // Step 71: a new order every visit, different for each man. What he did, opened and his habits are\n  // read once when the visit starts (or he changes the challenge), so nothing jumps while he scrolls.\n  const [refreshes, setRefreshes] = useState(0);\n  const [visit, setVisit] = useState<{ seed: string; done: Record<string, string>; opened: Record<string, string>; habits: Habits } | null>(null);\n  useEffect(() => {\n    if (!tried.ready || !social.ready) return;\n    setVisit({ seed: visitSeed(accountId), done: { ...tried.done }, opened: { ...social.history }, habits: habitsStore.get() });\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [tried.ready, social.ready, filter, accountId, refreshes]);\n  // Pull to refresh (Step 77) starts a new visit: a fresh order, from the top\n  useEffect(() => {\n    const on = () => {\n      setShown(PAGE);\n      setRefreshes((n) => n + 1);\n    };\n    window.addEventListener(DISCOVER_REFRESH, on);\n    return () => window.removeEventListener(DISCOVER_REFRESH, on);\n  }, []);\n  const cards = useMemo(() => {\n    if (!visit) return [];\n    const picked = filter === \"all\" ? all : all.filter((c) => c.spec.challenges.includes(filter));\n    return orderCards(picked, `${visit.seed}:${filter}`, { interests: social.interests, opened: visit.opened, liked: { ...helpedYes(feed.tried), ...tried.liked }, done: visit.done }, cfg);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [all, filter, visit, cfg]);\n  const reels = useMemo(() => (visit ? orderReels(items.filter(isReel), visit.seed, visit.opened, cfg) : []), [items, visit, cfg]);\n  // Reels inside the feed: how often depends on the Studio setting and (if allowed) on his habits\n  // Step 80: inside a circle, only the reels staff put in that circle\n  const reelSpots = useMemo(() => {\n    if (!visit) return new Map<number, ContentItem>();\n    const here = filter === \"all\" ? reels : reels.filter((r) => circlesOf(r).includes(filter));\n    return placeReels(cards.length, here, reelEvery(cfg, visit.habits));\n  }, [visit, filter, reels, cards.length, cfg]);\n\n  // Load more cards as he nears the end\n  const sentinel = useRef<HTMLDivElement>(null);\n  const more = cards.length > shown;\n  useEffect(() => {\n    const el = sentinel.current;\n    if (!el || !more || typeof IntersectionObserver === \"undefined\") return;\n    const io = new IntersectionObserver((e) => e.some((x) => x.isIntersecting) && setShown((n) => n + PAGE), { rootMargin: \"800px 0px\" });\n    io.observe(el);\n    return () => io.disconnect();\n  }, [more, shown]);\n\n  const pick = (id: FeedFilter) => {\n    triedStore.setFilter(id === filter && id !== \"all\" ? \"all\" : id);\n    setShown(PAGE);\n    top.current?.scrollIntoView({ block: \"start\", behavior: \"smooth\" });\n  };\n\n  // Tapping a reel opens the full-screen viewer with sound on. The tapped reel comes first and the ones\n  // before it go to the end (he has seen those in the feed), so pulling down on it closes the viewer (Step 77).\n  const openReels = (start: number, list = reels) =>\n    setViewer({ list: start > 0 ? [...list.slice(start), ...list.slice(0, start)] : list, start: 0, sound: true });\n  if (!tried.ready || !social.ready || !visit) return <ActionFeedSkeleton />;\n\n  const left = (id: FeedFilter) => (id === \"all\" ? all : all.filter((c) => c.spec.challenges.includes(id))).some((c) => !tried.done[c.item.id]);\n  const current = CHALLENGES.find((c) => c.id === filter) ?? CHALLENGES[0];\n\n  return (\n    <div className=\"mx-auto w-full max-w-[480px] space-y-4\">\n      <section aria-labelledby=\"challenge-h\" className=\"-mx-5 scroll-mt-4 lg:mx-0\" ref={top}>\n        <h2 id=\"challenge-h\" className=\"px-5 font-display text-[1.25rem] font-bold leading-tight lg:px-0\">\n          {t(\"What are you dealing with?\")}\n        </h2>\n        <div role=\"tablist\" aria-label={t(\"What are you dealing with?\")} className=\"no-scrollbar mt-3 flex gap-3.5 overflow-x-auto px-5 pb-1 lg:px-0\">\n          {CHALLENGES.map(({ id, label, icon: Icon }) => {\n            const on = filter === id;\n            const fresh = left(id);\n            return (\n              <button\n                key={id}\n                role=\"tab\"\n                aria-selected={on}\n                onClick={() => pick(id)}\n                className=\"flex w-[74px] shrink-0 flex-col items-center gap-1.5 transition-transform active:scale-95\"\n              >\n                {/* The ring is coloured while there are cards here he hasn't tried yet */}\n                <span\n                  className={`rounded-full p-[2.5px] ${fresh ? \"bg-[conic-gradient(from_200deg,var(--honey),var(--mint-strong),var(--forest),var(--honey))]\" : \"bg-line\"}`}\n                >\n                  <span className=\"block rounded-full bg-bg p-[2.5px]\">\n                    <span\n                      className={`flex h-[60px] w-[60px] items-center justify-center rounded-full transition-colors ${on ? \"bg-forest text-white\" : \"bg-surface text-forest ring-1 ring-line\"}`}\n                    >\n                      <Icon size={24} strokeWidth={2} aria-hidden />\n                    </span>\n                  </span>\n                </span>\n                <span className={`line-clamp-2 text-center text-[0.6875rem] leading-tight ${on ? \"font-bold text-ink\" : \"font-medium text-ink-soft\"}`}>{t(label)}</span>\n              </button>\n            );\n          })}\n        </div>\n      </section>\n\n      {/* Kito lives here on a phone, so his floating button doesn't have to sit on the cards (Step 73) */}\n      <button\n        type=\"button\"\n        onClick={openKito}\n        className=\"flex w-full items-center gap-2.5 rounded-full bg-surface py-1 pl-1 pr-4 text-left ring-1 ring-line transition-transform active:scale-[0.98] lg:hidden\"\n      >\n        <KitoMark size={36} />\n        <span className=\"flex-1 truncate text-sm text-ink-soft\">{t(\"Ask Kito…\")}</span>\n        <Send size={16} className=\"text-forest\" aria-hidden />\n      </button>\n\n      {/* A few days after he did a card: did it help? (Step 79) */}\n      <HelpedCheck items={items} />\n\n      {filter !== \"all\" && (\n        <p className=\"flex items-center justify-between gap-2 text-xs text-ink-soft\">\n          <span>\n            {t(\"{n} things to try for: {challenge}\", { n: cards.length, challenge: t(current.label).toLowerCase() })}\n          </span>\n          <button onClick={() => pick(\"all\")} className=\"font-semibold text-forest\">\n            {t(\"Show all\")}\n          </button>\n        </p>\n      )}\n\n      <div className=\"-mx-3 space-y-3 lg:mx-0 lg:space-y-4\">\n        {cards.slice(0, shown).map((c, i) => {\n          // Reels between the cards: full width, the one on screen plays silently (each reel shows once)\n          const r = reelSpots.get(i);\n          return (\n            <Fragment key={`${filter}-${c.item.id}`}>\n              {r && <ReelPost reel={r} onOpen={() => openReels(reels.indexOf(r))} />}\n              <ActionPost card={c} first={i === 0} done={Boolean(tried.done[c.item.id])} liked={Boolean(tried.liked[c.item.id])} saved={Boolean(social.bookmarks[c.item.id])} />\n            </Fragment>\n          );\n        })}\n      </div>\n\n      {more ? (\n        <div ref={sentinel} className=\"-mx-3 h-[40vh] animate-pulse rounded-[20px] lg:mx-0 bg-surface ring-1 ring-line\" aria-hidden />\n      ) : (\n        <EndOfFeed filter={filter} onPick={pick} t={t} />\n      )}\n      {viewer && <ReelsViewer reels={viewer.list} start={viewer.start} withSound={viewer.sound} onClose={() => setViewer(null)} />}\n    </div>\n  );\n}\n\nfunction EndOfFeed({ filter, onPick, t }: { filter: FeedFilter; onPick: (id: FeedFilter) => void; t: T }) {\n  return (\n    <section className=\"rounded-[20px] bg-forest-deep p-5 text-center text-white\">\n      <p className=\"font-display text-xl font-bold\">{t(\"That's everything for now\")}</p>\n      <p className=\"mt-1 text-sm text-mint\">{t(\"Pick one you haven't done yet, and do it tonight.\")}</p>\n      <div className=\"mt-4 flex flex-wrap justify-center gap-2\">\n        {CHALLENGES.filter((c) => c.id !== filter && c.id !== \"all\")\n          .slice(0, 4)\n          .map((c) => (\n            <button key={c.id} onClick={() => onPick(c.id)} className=\"rounded-full bg-white/10 px-3.5 py-2 text-xs font-semibold text-white ring-1 ring-white/20\">\n              {t(c.label)}\n            </button>\n          ))}\n      </div>\n      <Link href=\"/social?tab=community\" className=\"mt-4 inline-flex items-center gap-1.5 text-sm font-semibold text-mint-strong\">\n        <MessageCircle size={15} /> {t(\"Ask the community\")}\n      </Link>\n    </section>\n  );\n}\n\n/** One card in the feed, Instagram-post style. Also used by the Studio's Card maker preview. */\nexport function ActionPost({ card, first, done, liked, saved }: { card: Card; first: boolean; done: boolean; liked: boolean; saved: boolean }) {\n  const { item, spec } = card;\n  const t = useT();\n  const sw = t.lang === \"sw\";\n  const showToast = useToast();\n  const title = sw && item.titleSw ? item.titleSw : item.title;\n  const hook = sw && item.summarySw ? item.summarySw : item.summary;\n  const why = sw ? spec.whySw : spec.why;\n  const need = sw ? spec.needSw : spec.need;\n  const TypeIcon = TYPE_ICON[spec.type];\n  const href = contentHref(item.id);\n\n  const slides: React.ReactNode[] = [\n    <HookSlide key=\"hook\" item={item} spec={spec} title={title} hook={hook} first={first} t={t} />,\n    ...(item.videoUrl || item.audioUrl ? [<MediaSlide key=\"media\" item={item} t={t} />] : []),\n    ...(need?.length ? [<NeedSlide key=\"need\" need={need} t={t} />] : []),\n    ...spec.steps.map((s, i) => (\n      <StepSlide key={`s${i}`} n={i + 1} total={spec.steps.length} title={sw ? s.titleSw : s.title} text={sw ? s.textSw : s.text} t={t} />\n    )),\n    ...(why ? [<WhySlide key=\"why\" why={why} t={t} />] : []),\n  ];\n\n  const share = async () => {\n    const url = `${location.origin}${href}`;\n    try {\n      if (navigator.share) {\n        await navigator.share({ title, url });\n        return;\n      }\n      await navigator.clipboard.writeText(url);\n      showToast(t(\"Link copied\"));\n    } catch {\n      // he closed the share sheet\n    }\n  };\n\n  return (\n    <article className=\"overflow-hidden rounded-[20px] bg-surface ring-1 ring-line\" aria-label={title}>\n      <header className=\"flex items-center gap-2.5 px-3 py-2\">\n        <span className=\"flex h-8 w-8 shrink-0 items-center justify-center rounded-full bg-mint text-forest\">\n          <TypeIcon size={16} aria-hidden />\n        </span>\n        <div className=\"min-w-0 flex-1\">\n          <p className=\"truncate text-[0.8125rem] font-bold leading-tight\">{t(TYPE_LABEL[spec.type])}</p>\n          <p className=\"truncate text-[0.6875rem] text-ink-soft\">{t(\"{n} min\", { n: item.minutes })} · {item.origin ? \"@kayaniherbs\" : \"Kayani Herbs\"}</p>\n        </div>\n        <span\n          className={`shrink-0 rounded-full px-2.5 py-1 text-[0.6875rem] font-bold ${spec.results === \"tonight\" ? \"bg-honey text-on-honey\" : \"bg-mint text-forest\"}`}\n        >\n          {t(RESULT_LABEL[spec.results])}\n        </span>\n      </header>\n\n      <Carousel label={title} t={t} onSwipe={habitsStore.cardUsed}>\n        {slides}\n      </Carousel>\n\n      <div className=\"flex items-center px-1\">\n        <IconButton\n          label={t(liked ? \"Helped ✓\" : \"This helped\")}\n          pressed={liked}\n          onClick={() => {\n            const now = triedStore.toggleLike(item.id);\n            habitsStore.cardUsed();\n            if (now) showToast(t(\"Glad it helped\"));\n          }}\n        >\n          <Heart size={22} className={liked ? \"text-red-500\" : \"\"} fill={liked ? \"currentColor\" : \"none\"} />\n        </IconButton>\n        <IconButton label={t(\"Share\")} onClick={share}>\n          <Send size={21} />\n        </IconButton>\n        <Link href={href} className=\"ml-1 flex items-center gap-1 rounded-full px-2 py-2 text-xs font-semibold text-ink-soft\">\n          {t(\"Full page\")} <ArrowRight size={13} />\n        </Link>\n        <span className=\"flex-1\" />\n        <IconButton\n          label={t(saved ? \"Remove from saved\" : \"Save for later\")}\n          pressed={saved}\n          onClick={() => {\n            const now = socialStore.toggleBookmark(item.id);\n            habitsStore.cardUsed();\n            if (now) trackContent(item.id, \"save\");\n            showToast(t(now ? \"Saved for later\" : \"Removed from saved\"));\n            if (now) inviteToAccount(\"first-save\");\n          }}\n        >\n          <Bookmark size={21} fill={saved ? \"currentColor\" : \"none\"} />\n        </IconButton>\n      </div>\n\n      <div className=\"px-3 pb-3\">\n        <p className=\"line-clamp-2 text-[0.875rem] font-bold leading-snug\">{title}</p>\n        <div className=\"mt-2 flex gap-2\">\n          <button\n            onClick={(e) => {\n              const now = triedStore.toggleDone(item.id, done);\n              habitsStore.cardUsed();\n              if (now) {\n                haptic(\"done\");\n                flyPoints(e.currentTarget, TRIED_POINTS); // Step 79: doing a card earns points\n                trackContent(item.id, \"complete\");\n                showToast(t(\"Nice one, bro. Keep going.\"));\n              }\n            }}\n            aria-pressed={done}\n            className={`flex flex-1 items-center justify-center gap-2 rounded-full py-2.5 text-sm font-bold transition-transform active:scale-[0.98] ${\n              done ? \"bg-mint text-forest\" : \"bg-forest text-white\"\n            }`}\n          >\n            {done ? (\n              <>\n                <Check size={16} /> {t(\"Done. Do it again anytime\")}\n              </>\n            ) : (\n              <>\n                {t(\"I did it\")} <span className=\"rounded-full bg-honey px-1.5 py-px text-[0.6875rem] font-bold text-on-honey\">+{TRIED_POINTS}</span>\n              </>\n            )}\n          </button>\n          {spec.tool === \"pelvic-floor\" && (\n            <Link\n              href={contentHref(TIMER_ID)}\n              className=\"flex shrink-0 items-center justify-center gap-1.5 rounded-full px-4 py-2.5 text-sm font-bold text-forest ring-1 ring-line\"\n            >\n              <Timer size={16} /> {t(\"Timer\")}\n            </Link>\n          )}\n        </div>\n      </div>\n    </article>\n  );\n}\n\nfunction IconButton({ label, pressed, onClick, children }: { label: string; pressed?: boolean; onClick: () => void; children: React.ReactNode }) {\n  return (\n    <button\n      type=\"button\"\n      aria-label={label}\n      aria-pressed={pressed}\n      onClick={onClick}\n      className=\"flex h-10 w-10 items-center justify-center rounded-full text-ink transition-transform active:scale-90\"\n    >\n      {children}\n    </button>\n  );\n}\n\n/* ───────────── Carousel ───────────── */\n\nfunction Carousel({ children, label, t, onSwipe }: { children: React.ReactNode[]; label: string; t: T; onSwipe?: () => void }) {\n  const ref = useRef<HTMLDivElement>(null);\n  const [index, setIndex] = useState(0);\n  const swiped = useRef(false);\n  const count = children.length;\n\n  const onScroll = useCallback(() => {\n    const el = ref.current;\n    if (!el) return;\n    const i = Math.round(el.scrollLeft / el.clientWidth);\n    setIndex(i);\n    // The first time he swipes into the steps, it counts as using the card (Step 71: reading vs reels)\n    if (i > 0 && !swiped.current) {\n      swiped.current = true;\n      onSwipe?.();\n    }\n  }, [onSwipe]);\n  const go = (i: number) => {\n    const el = ref.current;\n    if (el) el.scrollTo({ left: Math.max(0, Math.min(count - 1, i)) * el.clientWidth, behavior: \"smooth\" });\n  };\n\n  return (\n    <div className=\"group relative\" role=\"region\" aria-roledescription=\"carousel\" aria-label={label}>\n      {/* overflow-x-auto also tells the tab pager to leave this swipe alone */}\n      <div ref={ref} onScroll={onScroll} className=\"no-scrollbar flex snap-x snap-mandatory overflow-x-auto overscroll-x-contain\">\n        {children.map((s, i) => (\n          <div key={i} className=\"aspect-[5/4] w-full shrink-0 snap-center\" aria-roledescription=\"slide\" aria-label={`${i + 1} / ${count}`} aria-hidden={i !== index}>\n            {s}\n          </div>\n        ))}\n      </div>\n      <span className=\"pointer-events-none absolute right-2.5 top-2.5 rounded-full bg-black/45 px-2 py-0.5 text-[0.6875rem] font-bold tabular-nums text-white backdrop-blur\">\n        {index + 1}/{count}\n      </span>\n      {/* Arrows for mouse users on a computer */}\n      <button\n        onClick={() => go(index - 1)}\n        aria-label={t(\"Previous\")}\n        className={`absolute left-2 top-1/2 hidden h-9 w-9 -translate-y-1/2 items-center justify-center rounded-full bg-white/90 text-ink shadow transition-opacity lg:flex ${index === 0 ? \"pointer-events-none opacity-0\" : \"opacity-0 group-hover:opacity-100\"}`}\n      >\n        <ChevronLeft size={18} />\n      </button>\n      <button\n        onClick={() => go(index + 1)}\n        aria-label={t(\"Next\")}\n        className={`absolute right-2 top-1/2 hidden h-9 w-9 -translate-y-1/2 items-center justify-center rounded-full bg-white/90 text-ink shadow transition-opacity lg:flex ${index === count - 1 ? \"pointer-events-none opacity-0\" : \"opacity-0 group-hover:opacity-100\"}`}\n      >\n        <ChevronRight size={18} />\n      </button>\n      <div className=\"flex justify-center gap-1.5 pt-2\" aria-hidden>\n        {children.map((_, i) => (\n          <span key={i} className={`h-1.5 rounded-full transition-all ${i === index ? \"w-4 bg-forest\" : \"w-1.5 bg-line\"}`} />\n        ))}\n      </div>\n    </div>\n  );\n}\n\n/* ───────────── Slides ───────────── */\n\nfunction HookSlide({ item, spec, title, hook, first, t }: { item: ContentItem; spec: ActionSpec; title: string; hook: string; first: boolean; t: T }) {\n  const steps = spec.steps.length;\n  return (\n    <div className=\"relative h-full w-full overflow-hidden\">\n      <Cover item={item} className=\"absolute inset-0 h-full w-full\" showPlay={false} />\n      <div className=\"absolute inset-0 bg-gradient-to-t from-black/85 via-black/45 to-black/5\" />\n      <div className=\"absolute inset-x-0 bottom-0 px-4 pb-3.5 text-white\">\n        <p className=\"text-[0.6875rem] font-bold uppercase tracking-wider text-mint-strong\">{t(TYPE_LABEL[spec.type])}</p>\n        <h3 className=\"mt-1 line-clamp-3 font-display text-[1.4375rem] font-bold leading-[1.1]\">{title}</h3>\n        <p className=\"mt-1.5 line-clamp-2 text-[0.875rem] leading-snug text-white/85\">{hook}</p>\n        <p className=\"mt-2.5 flex items-center gap-1.5 text-[0.8125rem] font-semibold text-white\">\n          <span className=\"inline-flex w-5 shrink-0 justify-center\">\n            <Hand size={15} className={first ? \"swipe-hand\" : \"\"} aria-hidden />\n          </span>\n          {t(steps === 1 ? \"Swipe for the step\" : \"Swipe for {n} steps\", { n: steps })}\n        </p>\n      </div>\n    </div>\n  );\n}\n\nfunction MediaSlide({ item, t }: { item: ContentItem; t: T }) {\n  const yt = youtubeId(item.videoUrl);\n  if (yt) return <YouTubeFrame id={yt} controls title={item.title} onEnded={() => trackContent(item.id, \"complete\")} className=\"h-full w-full\" />;\n  if (item.videoUrl) {\n    return (\n      <video\n        src={item.videoUrl}\n        poster={item.coverImageUrl}\n        controls\n        playsInline\n        preload=\"metadata\"\n        onEnded={() => trackContent(item.id, \"complete\")}\n        className=\"h-full w-full bg-black object-cover\"\n      />\n    );\n  }\n  return (\n    <div className=\"relative h-full w-full overflow-hidden\">\n      <Cover item={item} className=\"absolute inset-0 h-full w-full\" showPlay={false} />\n      <div className=\"absolute inset-0 bg-black/55\" />\n      <div className=\"absolute inset-x-0 bottom-0 px-4 pb-4\">\n        <p className=\"mb-2 text-[0.6875rem] font-bold uppercase tracking-wider text-mint-strong\">{t(\"Listen\")}</p>\n        <audio src={item.audioUrl} controls preload=\"metadata\" onEnded={() => trackContent(item.id, \"complete\")} className=\"w-full\" />\n      </div>\n    </div>\n  );\n}\n\n/** A text slide: the words sit in the middle, and long text scrolls instead of being cut off. */\nfunction Frame({ className, children }: { className: string; children: React.ReactNode }) {\n  return (\n    <div className={`relative flex h-full w-full flex-col overflow-y-auto overflow-x-hidden px-5 py-4 ${className}`}>\n      <div className=\"relative my-auto\">{children}</div>\n    </div>\n  );\n}\n\nfunction NeedSlide({ need, t }: { need: string[]; t: T }) {\n  return (\n    <Frame className=\"bg-mint text-forest-deep\">\n      <p className=\"text-[0.6875rem] font-bold uppercase tracking-wider text-forest\">{t(\"You need\")}</p>\n      <ul className={`mt-3 ${need.length > 4 ? \"space-y-1.5\" : \"space-y-2.5\"}`}>\n        {need.map((n, i) => (\n          <li key={i} className={`flex items-start gap-2.5 font-semibold leading-snug ${need.length > 4 ? \"text-[0.875rem]\" : \"text-[1rem]\"}`}>\n            <span className=\"mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-forest text-white\">\n              <Check size={12} />\n            </span>\n            {n}\n          </li>\n        ))}\n      </ul>\n    </Frame>\n  );\n}\n\nfunction StepSlide({ n, total, title, text, t }: { n: number; total: number; title?: string; text: string; t: T }) {\n  const long = text.length > 120;\n  return (\n    <div className=\"relative h-full w-full overflow-hidden bg-forest-deep text-white\">\n      <span className=\"pointer-events-none absolute -right-3 -top-8 font-display text-[10rem] font-bold leading-none text-white/[0.07]\" aria-hidden>\n        {n}\n      </span>\n      <Frame className=\"\">\n        <p className=\"text-[0.6875rem] font-bold uppercase tracking-wider text-mint-strong\">{t(\"Step {n} of {total}\", { n, total })}</p>\n        {title && <p className=\"mt-2 font-display text-[1.3125rem] font-bold leading-tight\">{title}</p>}\n        <p className={`${title ? `mt-1.5 ${long ? \"text-[0.9375rem]\" : \"text-[1rem]\"}` : `mt-2 font-semibold ${long ? \"text-[1rem]\" : \"text-[1.1875rem]\"}`} leading-snug text-white/95`}>{text}</p>\n      </Frame>\n    </div>\n  );\n}\n\nfunction WhySlide({ why, t }: { why: string; t: T }) {\n  return (\n    <Frame className=\"bg-surface\">\n      <p className=\"text-[0.6875rem] font-bold uppercase tracking-wider text-forest\">{t(\"The secret\")}</p>\n      <p className={`mt-2 font-display font-bold leading-snug text-ink ${why.length > 110 ? \"text-[1.0625rem]\" : \"text-[1.1875rem]\"}`}>{why}</p>\n      <p className=\"mt-3 text-[0.8125rem] text-ink-soft\">{t(\"Tried it? Tap \\\"I did it\\\" below.\")}</p>\n    </Frame>\n  );\n}\n",
 "src/components/studio/ContentList.tsx": "\"use client\";\n\n// Content library: search, filter, sort, bulk actions, performance, and a publishing calendar.\n// Every action goes through the content repo → Supabase, where the database checks the admin's role.\n\nimport { useEffect, useMemo, useState } from \"react\";\nimport Link from \"next/link\";\nimport { CalendarDays, Clapperboard, ChevronLeft, ChevronRight, Copy, Plus, Search } from \"lucide-react\";\nimport Cover from \"@/components/social/Cover\";\nimport { useStudio } from \"@/components/admin/AdminShell\";\nimport { Badge, Confirm, Empty, ErrorBox, Loading, PageHeader, Segmented, btn, input } from \"@/components/admin/ui\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { LIBRARY } from \"@/lib/content/library\";\nimport { CIRCLES, NO_CIRCLE, circleNames, circlesOf } from \"@/lib/content/circles\";\nimport { actionOf } from \"@/lib/content/actions\";\nimport type { ChallengeId } from \"@/lib/content/types\";\n\n/** Filter by Discover circle (\"last\"…), or \"none:fertility\" for content outside the circles. */\nfunction inCircle(c: ContentItem, f: string): boolean {\n  if (f === \"all\") return true;\n  const circles = circlesOf({ ...c, action: actionOf(c) });\n  if (f.startsWith(\"none:\")) return circles.length === 0 && c.topic === f.slice(5);\n  return circles.includes(f as ChallengeId);\n}\nimport { publishProblems } from \"@/lib/studio/validate\";\nimport { getContentRepo } from \"@/lib/content/repo\";\nimport { KIND_LABEL } from \"@/lib/content/select\";\nimport type { ContentItem, ContentKind, ContentStatus } from \"@/lib/content/types\";\nimport { displayStatus, STATUS_LABEL, STATUS_STYLE, type DisplayStatus } from \"@/lib/admin/contentStatus\";\nimport { select } from \"@/lib/admin/api\";\n\ntype Tab = \"all\" | DisplayStatus | \"builtin\";\ntype Stats = Record<string, { views: number; completes: number; saves: number }>;\nconst PAGE = 20;\n\nexport default function ContentList() {\n  const studio = useStudio();\n  const showToast = useToast();\n  const canPublish = studio.can(\"content.publish\");\n  const [items, setItems] = useState<ContentItem[] | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [stats, setStats] = useState<Stats | null>(null);\n  const [tab, setTab] = useState<Tab>(\"all\");\n  const [kind, setKind] = useState<\"all\" | ContentKind>(\"all\");\n  const [topic, setTopic] = useState(\"all\");\n  const [since, setSince] = useState(\"all\");\n  const [sort, setSort] = useState<\"updated\" | \"views\" | \"title\">(\"updated\");\n  const [q, setQ] = useState(\"\");\n  const [page, setPage] = useState(0);\n  const [view, setView] = useState<\"list\" | \"calendar\">(\"list\");\n  const [picked, setPicked] = useState<Set<string>>(new Set());\n  const [bulk, setBulk] = useState<null | { action: ContentStatus | \"delete\"; label: string }>(null);\n  const [busy, setBusy] = useState(false);\n\n  useEffect(() => {\n    const repo = getContentRepo();\n    const load = () =>\n      repo\n        .listAll()\n        .then((list) => {\n          setItems(list);\n          setError(null);\n        })\n        .catch((e: Error) => setError(e.message));\n    void load();\n    return repo.subscribe(load);\n  }, []);\n\n  // Performance (last 30 days), counted without knowing who viewed\n  useEffect(() => {\n    if (!studio.can(\"analytics.view\")) return;\n    const from = new Date(Date.now() - 30 * 864e5).toISOString().slice(0, 10);\n    select<{ content_id: string; views: number; completes: number; saves: number }>(\"content_stats_daily\", \"content_id,views,completes,saves\", (q) => q.gte(\"day\", from))\n      .then((rows) => {\n        const s: Stats = {};\n        for (const r of rows) {\n          const t = (s[r.content_id] ??= { views: 0, completes: 0, saves: 0 });\n          t.views += r.views;\n          t.completes += r.completes;\n          t.saves += r.saves;\n        }\n        setStats(s);\n      })\n      .catch(() => setStats(null)); // shown as \"not tracked yet\"\n  }, [studio]);\n\n  const mine = useMemo(() => new Set((items ?? []).map((c) => c.id)), [items]);\n  const count = (s: DisplayStatus) => (items ?? []).filter((c) => displayStatus(c) === s).length;\n\n  const shown = useMemo(() => {\n    const list = tab === \"builtin\" ? LIBRARY.map((c) => ({ ...c, builtIn: true })) : (items ?? []).filter((c) => tab === \"all\" || displayStatus(c) === tab);\n    const words = q.toLowerCase().split(/\\s+/).filter(Boolean);\n    const after = since === \"all\" ? 0 : Date.now() - Number(since) * 864e5;\n    return list\n      .filter((c) => (kind === \"all\" || c.kind === kind) && inCircle(c, topic))\n      .filter((c) => !after || (c.updatedAt && new Date(c.updatedAt).getTime() >= after))\n      .filter((c) => {\n        const text = `${c.title} ${c.titleSw ?? \"\"} ${c.id} ${c.tags.join(\" \")}`.toLowerCase();\n        return words.every((w) => text.includes(w));\n      })\n      .sort((a, b) =>\n        sort === \"title\"\n          ? a.title.localeCompare(b.title)\n          : sort === \"views\"\n            ? (stats?.[b.id]?.views ?? 0) - (stats?.[a.id]?.views ?? 0)\n            : (b.updatedAt ?? \"\").localeCompare(a.updatedAt ?? \"\"),\n      );\n  }, [items, tab, q, kind, topic, since, sort, stats]);\n\n  useEffect(() => setPage(0), [tab, q, kind, topic, since, sort]);\n  useEffect(() => setPicked(new Set()), [tab]);\n  const pageItems = shown.slice(page * PAGE, page * PAGE + PAGE);\n  const pages = Math.max(1, Math.ceil(shown.length / PAGE));\n  const pickedItems = (items ?? []).filter((c) => picked.has(c.id));\n\n  async function runBulk() {\n    if (!bulk) return;\n    setBusy(true);\n    const repo = getContentRepo();\n    let ok = 0;\n    const errors: string[] = [];\n    for (const c of pickedItems) {\n      try {\n        if (bulk.action === \"published\" || bulk.action === \"review\") {\n          const missing = publishProblems(c);\n          if (missing.length) throw new Error(`not ready — ${missing[0]}`);\n        }\n        if (bulk.action === \"delete\") await repo.remove(c.id);\n        else await repo.setStatus(c.id, bulk.action);\n        ok++;\n      } catch (e) {\n        errors.push(`${c.title}: ${(e as Error).message}`);\n      }\n    }\n    setBusy(false);\n    setBulk(null);\n    setPicked(new Set());\n    showToast(errors.length ? `${ok} done, ${errors.length} not changed` : `${ok} ${ok === 1 ? \"item\" : \"items\"} updated`);\n    if (errors.length) setError(errors.slice(0, 3).join(\" · \"));\n  }\n\n  const tabs: { id: Tab; label: string }[] = [\n    { id: \"all\", label: `Yours (${items?.length ?? 0})` },\n    { id: \"draft\", label: `Drafts (${count(\"draft\")})` },\n    { id: \"review\", label: `In review (${count(\"review\")})` },\n    { id: \"scheduled\", label: `Scheduled (${count(\"scheduled\")})` },\n    { id: \"published\", label: `Published (${count(\"published\")})` },\n    { id: \"archived\", label: `Archived (${count(\"archived\")})` },\n    { id: \"builtin\", label: `Built-in (${LIBRARY.length})` },\n  ];\n\n  return (\n    <div className=\"space-y-5\">\n      <PageHeader\n        title=\"Content\"\n        sub={items === null ? \"Loading…\" : `${count(\"published\")} live · ${count(\"review\")} waiting for review · ${count(\"scheduled\")} scheduled · ${LIBRARY.length} built-in`}\n        actions={\n          <>\n            <Segmented\n              label=\"View\"\n              value={view}\n              onChange={setView}\n              options={[\n                { id: \"list\", label: \"List\" },\n                { id: \"calendar\", label: \"Calendar\" },\n              ]}\n            />\n            <Link href=\"/studio/edit?place=reels\" className={btn.ghost}>\n              <Clapperboard size={16} /> Upload a reel\n            </Link>\n            <Link href=\"/studio/edit\" className={btn.primary}>\n              <Plus size={16} /> New content\n            </Link>\n          </>\n        }\n      />\n\n      {error && <ErrorBox error={error} onRetry={() => setError(null)} />}\n\n      {view === \"calendar\" ? (\n        <Calendar items={items ?? []} />\n      ) : (\n        <>\n          {/* Filters: one row above the list */}\n          <div className=\"space-y-3\">\n            <div className=\"flex gap-1 overflow-x-auto rounded-full bg-surface p-1 ring-1 ring-line [scrollbar-width:none]\" role=\"tablist\" aria-label=\"Status\">\n              {tabs.map((t) => (\n                <button\n                  key={t.id}\n                  role=\"tab\"\n                  aria-selected={tab === t.id}\n                  onClick={() => setTab(t.id)}\n                  className={`shrink-0 rounded-full px-3.5 py-1.5 text-xs font-semibold ${tab === t.id ? \"bg-forest-deep text-white\" : \"text-ink-soft\"}`}\n                >\n                  {t.label}\n                </button>\n              ))}\n            </div>\n            <div className=\"grid gap-2 sm:grid-cols-2 lg:grid-cols-[minmax(0,2fr)_repeat(4,minmax(0,1fr))]\">\n              <label className=\"flex items-center gap-2 rounded-xl bg-surface px-3 ring-1 ring-line focus-within:ring-2 focus-within:ring-forest\">\n                <Search size={14} className=\"text-ink-soft\" />\n                <input value={q} onChange={(e) => setQ(e.target.value)} placeholder=\"Search titles, tags, addresses\" aria-label=\"Search content\" className=\"w-full bg-transparent py-2.5 text-sm outline-none\" />\n              </label>\n              <select aria-label=\"Type\" value={kind} onChange={(e) => setKind(e.target.value as typeof kind)} className={input}>\n                <option value=\"all\">All types</option>\n                {(Object.keys(KIND_LABEL) as ContentKind[]).map((k) => (\n                  <option key={k} value={k}>\n                    {KIND_LABEL[k]}\n                  </option>\n                ))}\n              </select>\n              {/* The same circles men tap at the top of Discover (Step 80) */}\n              <select aria-label=\"Circle\" value={topic} onChange={(e) => setTopic(e.target.value)} className={input}>\n                <option value=\"all\">All circles</option>\n                {CIRCLES.map((c) => (\n                  <option key={c.id} value={c.id}>\n                    {c.label}\n                  </option>\n                ))}\n                {NO_CIRCLE.map((n) => (\n                  <option key={n.topic} value={`none:${n.topic}`}>\n                    {n.label} (no circle)\n                  </option>\n                ))}\n              </select>\n              <select aria-label=\"Changed\" value={since} onChange={(e) => setSince(e.target.value)} className={input}>\n                <option value=\"all\">Any date</option>\n                <option value=\"7\">Changed in 7 days</option>\n                <option value=\"30\">Changed in 30 days</option>\n                <option value=\"90\">Changed in 90 days</option>\n              </select>\n              <select aria-label=\"Sort\" value={sort} onChange={(e) => setSort(e.target.value as typeof sort)} className={input}>\n                <option value=\"updated\">Newest change</option>\n                <option value=\"views\">Most viewed (30 days)</option>\n                <option value=\"title\">Title A–Z</option>\n              </select>\n            </div>\n          </div>\n\n          {tab === \"builtin\" && (\n            <p className=\"rounded-2xl bg-mint/60 px-4 py-3 text-sm text-forest-deep\">\n              These came with the app (samples and the adapted Instagram posts). Open one to edit a copy. When you publish the copy, it replaces\n              the built-in version for everyone.\n            </p>\n          )}\n\n          {/* Bulk actions */}\n          {picked.size > 0 && (\n            <div className=\"sticky top-16 z-10 flex flex-wrap items-center gap-2 rounded-2xl bg-forest-deep px-4 py-2.5 text-sm text-white lg:top-2\">\n              <span className=\"mr-auto font-semibold\">{picked.size} selected</span>\n              <button className=\"rounded-full bg-white/15 px-3 py-1.5 text-xs font-semibold\" onClick={() => setBulk({ action: \"review\", label: \"Submit for review\" })}>\n                Submit for review\n              </button>\n              <button className=\"rounded-full bg-white/15 px-3 py-1.5 text-xs font-semibold\" onClick={() => setBulk({ action: \"draft\", label: \"Move to drafts\" })}>\n                Move to drafts\n              </button>\n              {canPublish && (\n                <>\n                  <button className=\"rounded-full bg-white/15 px-3 py-1.5 text-xs font-semibold\" onClick={() => setBulk({ action: \"published\", label: \"Publish\" })}>\n                    Publish\n                  </button>\n                  <button className=\"rounded-full bg-white/15 px-3 py-1.5 text-xs font-semibold\" onClick={() => setBulk({ action: \"archived\", label: \"Archive\" })}>\n                    Archive\n                  </button>\n                </>\n              )}\n              <button className=\"rounded-full bg-red-600 px-3 py-1.5 text-xs font-semibold\" onClick={() => setBulk({ action: \"delete\", label: \"Delete\" })}>\n                Delete\n              </button>\n              <button className=\"px-2 text-xs underline\" onClick={() => setPicked(new Set())}>\n                Clear\n              </button>\n            </div>\n          )}\n\n          {items === null && tab !== \"builtin\" && !error ? (\n            <Loading />\n          ) : shown.length === 0 ? (\n            <div className=\"rounded-2xl bg-surface ring-1 ring-line\">\n              <Empty title={q || kind !== \"all\" || topic !== \"all\" || since !== \"all\" ? \"Nothing matches these filters\" : tab === \"all\" ? \"You haven't written anything yet\" : \"Nothing here\"}>\n                {tab === \"all\" && !q ? \"Press “New content” to write your first guide or article.\" : \"Try clearing a filter.\"}\n              </Empty>\n            </div>\n          ) : (\n            <div className=\"overflow-hidden rounded-2xl bg-surface ring-1 ring-line\">\n              <ul className=\"divide-y divide-line\">\n                {pageItems.map((c) => {\n                  const ds = c.builtIn ? null : displayStatus(c);\n                  const s = stats?.[c.id];\n                  return (\n                    <li key={c.id} className=\"flex items-center gap-3 p-3 pr-4 hover:bg-bg\">\n                      {!c.builtIn && (\n                        <input\n                          type=\"checkbox\"\n                          aria-label={`Select ${c.title}`}\n                          className=\"h-4 w-4 shrink-0 accent-forest\"\n                          checked={picked.has(c.id)}\n                          onChange={(e) =>\n                            setPicked((p) => {\n                              const n = new Set(p);\n                              if (e.target.checked) n.add(c.id);\n                              else n.delete(c.id);\n                              return n;\n                            })\n                          }\n                        />\n                      )}\n                      <Link href={`/studio/edit?id=${encodeURIComponent(c.id)}`} className=\"flex min-w-0 flex-1 items-center gap-3\">\n                        <Cover item={c} className=\"hidden h-12 w-16 shrink-0 rounded-lg sm:block\" showPlay={false} />\n                        <div className=\"min-w-0 flex-1\">\n                          <p className=\"truncate text-sm font-semibold\">{c.title}</p>\n                          <p className=\"truncate text-xs text-ink-soft\">\n                            {KIND_LABEL[c.kind]} · {circleNames({ ...c, action: actionOf(c) })}\n                            {c.titleSw ? \" · EN + SW\" : \"\"}\n                            {c.kind === \"reel\" ? \" · on Discover\" : c.inManFeed ? \" · Man tab\" : \"\"}\n                            {c.aiGenerated ? \" · AI-assisted\" : \"\"}\n                            {ds === \"scheduled\" && c.publishAt\n                              ? ` · goes live ${new Date(c.publishAt).toLocaleString(\"en-GB\", { day: \"numeric\", month: \"short\", hour: \"2-digit\", minute: \"2-digit\" })}`\n                              : c.updatedAt\n                                ? ` · changed ${new Date(c.updatedAt).toLocaleDateString(\"en-GB\", { day: \"numeric\", month: \"short\" })}`\n                                : \"\"}\n                          </p>\n                        </div>\n                      </Link>\n                      <span className=\"hidden w-28 shrink-0 text-right text-[0.6875rem] tabular-nums text-ink-soft md:block\" title=\"Last 30 days: views · finished · saved\">\n                        {stats === null ? \"—\" : s ? `${s.views} · ${s.completes} · ${s.saves}` : \"0 · 0 · 0\"}\n                      </span>\n                      {c.builtIn ? (\n                        <Badge>{mine.has(c.id) ? \"Edited copy exists\" : \"Built-in\"}</Badge>\n                      ) : (\n                        ds && <span className={`shrink-0 rounded-full px-2.5 py-1 text-[0.6875rem] font-semibold ring-1 ${STATUS_STYLE[ds]}`}>{STATUS_LABEL[ds]}</span>\n                      )}\n                      <Link href={`/studio/edit?copy=${encodeURIComponent(c.id)}`} aria-label={`Duplicate ${c.title}`} title=\"Duplicate\" className=\"hidden shrink-0 text-ink-soft hover:text-ink sm:block\">\n                        <Copy size={15} />\n                      </Link>\n                    </li>\n                  );\n                })}\n              </ul>\n              <div className=\"flex items-center justify-between border-t border-line px-4 py-2.5 text-xs text-ink-soft\">\n                <span>\n                  {shown.length} {shown.length === 1 ? \"item\" : \"items\"}\n                  {stats !== null && <span className=\"hidden md:inline\"> · numbers = views · finished · saved, last 30 days</span>}\n                </span>\n                <div className=\"flex items-center gap-2\">\n                  <button aria-label=\"Previous page\" disabled={page === 0} onClick={() => setPage((p) => p - 1)} className=\"rounded-full p-1.5 ring-1 ring-line disabled:opacity-30\">\n                    <ChevronLeft size={14} />\n                  </button>\n                  <span>\n                    Page {page + 1} of {pages}\n                  </span>\n                  <button aria-label=\"Next page\" disabled={page >= pages - 1} onClick={() => setPage((p) => p + 1)} className=\"rounded-full p-1.5 ring-1 ring-line disabled:opacity-30\">\n                    <ChevronRight size={14} />\n                  </button>\n                </div>\n              </div>\n            </div>\n          )}\n        </>\n      )}\n\n      <Confirm\n        open={bulk !== null}\n        title={`${bulk?.label} ${picked.size} ${picked.size === 1 ? \"item\" : \"items\"}?`}\n        confirmLabel={bulk?.label ?? \"\"}\n        danger={bulk?.action === \"delete\"}\n        typeToConfirm={bulk?.action === \"delete\" ? \"delete\" : undefined}\n        busy={busy}\n        onConfirm={runBulk}\n        onClose={() => setBulk(null)}\n      >\n        {bulk?.action === \"published\"\n          ? \"They go live for men now (items that aren't ready, or AI drafts not yet checked, will be refused by the database and listed).\"\n          : bulk?.action === \"delete\"\n            ? \"They're removed for good. This can't be undone.\"\n            : bulk?.action === \"archived\"\n              ? \"They're taken out of the app but kept here.\"\n              : \"Their status changes. Nothing is deleted.\"}\n      </Confirm>\n    </div>\n  );\n}\n\n/** Month calendar: what went live, and what's scheduled to go live. */\nfunction Calendar({ items }: { items: ContentItem[] }) {\n  const [month, setMonth] = useState(() => {\n    const d = new Date();\n    return new Date(d.getFullYear(), d.getMonth(), 1);\n  });\n  const start = new Date(month);\n  start.setDate(1 - ((month.getDay() + 6) % 7)); // weeks start Monday\n  const days = Array.from({ length: 42 }, (_, i) => new Date(start.getFullYear(), start.getMonth(), start.getDate() + i));\n  const key = (d: Date) => `${d.getFullYear()}-${d.getMonth()}-${d.getDate()}`;\n  const byDay = new Map<string, { c: ContentItem; scheduled: boolean }[]>();\n  for (const c of items) {\n    const ds = displayStatus(c);\n    const when = ds === \"scheduled\" ? c.publishAt : ds === \"published\" ? c.publishedAt : undefined;\n    if (!when) continue;\n    const k = key(new Date(when));\n    byDay.set(k, [...(byDay.get(k) ?? []), { c, scheduled: ds === \"scheduled\" }]);\n  }\n  const today = key(new Date());\n  return (\n    <div className=\"rounded-2xl bg-surface p-4 ring-1 ring-line\">\n      <div className=\"mb-3 flex items-center justify-between\">\n        <button aria-label=\"Previous month\" onClick={() => setMonth((m) => new Date(m.getFullYear(), m.getMonth() - 1, 1))} className={btn.small}>\n          <ChevronLeft size={14} />\n        </button>\n        <p className=\"flex items-center gap-2 text-sm font-bold\">\n          <CalendarDays size={16} /> {month.toLocaleDateString(\"en-GB\", { month: \"long\", year: \"numeric\" })}\n        </p>\n        <button aria-label=\"Next month\" onClick={() => setMonth((m) => new Date(m.getFullYear(), m.getMonth() + 1, 1))} className={btn.small}>\n          <ChevronRight size={14} />\n        </button>\n      </div>\n      <div className=\"grid grid-cols-7 gap-px overflow-hidden rounded-xl bg-line text-xs ring-1 ring-line\">\n        {[\"Mon\", \"Tue\", \"Wed\", \"Thu\", \"Fri\", \"Sat\", \"Sun\"].map((d) => (\n          <div key={d} className=\"bg-surface px-2 py-1.5 font-semibold text-ink-soft\">\n            {d}\n          </div>\n        ))}\n        {days.map((d) => {\n          const list = byDay.get(key(d)) ?? [];\n          const inMonth = d.getMonth() === month.getMonth();\n          return (\n            <div key={d.toISOString()} className={`min-h-20 bg-surface p-1.5 ${inMonth ? \"\" : \"opacity-40\"}`}>\n              <p className={`mb-1 text-[0.6875rem] font-semibold ${key(d) === today ? \"inline-block rounded-full bg-forest px-1.5 text-white\" : \"text-ink-soft\"}`}>{d.getDate()}</p>\n              <ul className=\"space-y-1\">\n                {list.slice(0, 3).map(({ c, scheduled }) => (\n                  <li key={c.id}>\n                    <Link\n                      href={`/studio/edit?id=${encodeURIComponent(c.id)}`}\n                      className={`block truncate rounded px-1 py-0.5 text-[0.625rem] font-medium ${scheduled ? \"bg-sky-50 text-sky-800 dark:bg-sky-950/40 dark:text-sky-200\" : \"bg-mint text-forest-deep\"}`}\n                      title={`${scheduled ? \"Scheduled\" : \"Published\"}: ${c.title}`}\n                    >\n                      {c.title}\n                    </Link>\n                  </li>\n                ))}\n                {list.length > 3 && <li className=\"text-[0.625rem] text-ink-soft\">+{list.length - 3} more</li>}\n              </ul>\n            </div>\n          );\n        })}\n      </div>\n      <p className=\"mt-2 flex flex-wrap gap-3 text-[0.6875rem] text-ink-soft\">\n        <span className=\"flex items-center gap-1\">\n          <i className=\"inline-block h-2.5 w-2.5 rounded-sm bg-mint\" /> Published\n        </span>\n        <span className=\"flex items-center gap-1\">\n          <i className=\"inline-block h-2.5 w-2.5 rounded-sm bg-sky-100\" /> Scheduled\n        </span>\n        <span>To schedule, open an item and set &ldquo;Go live at&rdquo;.</span>\n      </p>\n    </div>\n  );\n}\n",
 "src/components/studio/Editor.tsx": "\"use client\";\n\nimport { CIRCLES, NO_CIRCLE, circlesOf, isCircle, setCircles } from \"@/lib/content/circles\";\nimport { useEffect, useMemo, useRef, useState } from \"react\";\nimport Link from \"next/link\";\nimport { useRouter } from \"next/navigation\";\nimport {\n  AlertTriangle,\n  ArrowLeft,\n  Archive,\n  CheckCircle2,\n  Clock,\n  Copy,\n  Film,\n  History,\n  Mic,\n  ImagePlus,\n  MapPin,\n  Loader2,\n  OctagonX,\n  Plus,\n  Trash2,\n  X,\n} from \"lucide-react\";\nimport Preview from \"./Preview\";\nimport { YouTubeFrame } from \"@/components/media/YouTubeFrame\";\nimport { cleanYouTubeUrl, isYouTubeShort, youtubeId } from \"@/lib/content/youtube\";\nimport { MAX_VIDEO_BYTES } from \"@/lib/content/repo\";\nimport { canShrink, shrinkVideo } from \"@/lib/studio/shrinkVideo\";\nimport { useStudio } from \"@/components/admin/AdminShell\";\nimport type { Version } from \"@/lib/content/repo\";\nimport { Notice } from \"./StudioGate\";\nimport {\n  displayStatus,\n  STATUS_LABEL,\n  STATUS_STYLE,\n} from \"@/lib/admin/contentStatus\";\nimport { Confirm, Drawer, btn } from \"@/components/admin/ui\";\nimport { useToast } from \"@/components/motion/Toast\";\nimport { LIBRARY, TOPICS } from \"@/lib/content/library\";\nimport { getContentRepo } from \"@/lib/content/repo\";\nimport { KIND_LABEL } from \"@/lib/content/select\";\nimport type {\n  ContentItem,\n  ContentKind,\n  ContentStatus,\n  QuizQuestion,\n  ToolId,\n} from \"@/lib/content/types\";\nimport { checkClaims } from \"@/lib/studio/claims\";\nimport { placesOf, presetFor, type PlaceId } from \"@/lib/studio/places\";\nimport type { ChallengeId, TopicId } from \"@/lib/content/types\";\nimport { actionOf } from \"@/lib/content/actions\";\nimport {\n  blankItem,\n  fromLines,\n  fromParagraphs,\n  ID_RULE,\n  publishProblems,\n  slugify,\n  toLines,\n  toParagraphs,\n} from \"@/lib/studio/validate\";\n\nconst KINDS: ContentKind[] = [\n  \"reel\",\n  \"article\",\n  \"guide\",\n  \"expert\",\n  \"video\",\n  \"quiz\",\n  \"tool\",\n  \"audio\",\n  \"infographic\",\n];\nconst TONES: ContentItem[\"cover\"][\"tone\"][] = [\n  \"forest\",\n  \"night\",\n  \"mint\",\n  \"sand\",\n  \"clay\",\n];\nconst MOTIFS: ContentItem[\"cover\"][\"motif\"][] = [\n  \"rings\",\n  \"waves\",\n  \"arc\",\n  \"grid\",\n  \"dots\",\n];\nconst TONE_SWATCH: Record<string, string> = {\n  forest: \"#0f5c46\",\n  night: \"#06261d\",\n  mint: \"#dff3ea\",\n  sand: \"#f1e8d8\",\n  clay: \"#efdcd0\",\n};\nconst TOOLS: { id: ToolId; label: string }[] = [\n  { id: \"pelvic-floor\", label: \"Pelvic floor trainer\" },\n  { id: \"doctor-check\", label: \"Should I see a doctor? check\" },\n];\n\ntype Texts = { body: string; bodySw: string; keyPoints: string; tags: string };\nconst textsOf = (c: ContentItem): Texts => ({\n  body: fromParagraphs(c.body),\n  bodySw: fromParagraphs(c.bodySw),\n  keyPoints: fromLines(c.keyPoints),\n  // Circle tags (\"last\", \"hard\"…) are set with the circle buttons, not typed (Step 80)\n  tags: c.tags.filter((t) => !isCircle(t)).join(\", \"),\n});\n\nconst compose = (draft: ContentItem, texts: Texts): ContentItem => ({\n  ...draft,\n  body: toParagraphs(texts.body),\n  bodySw: toParagraphs(texts.bodySw),\n  keyPoints: toLines(texts.keyPoints),\n  tags: [\n    ...new Set([\n      ...texts.tags\n        .split(\",\")\n        .map((t) => t.trim().toLowerCase())\n        .filter((t) => t && !isCircle(t)),\n      ...draft.tags.filter(isCircle),\n    ]),\n  ],\n});\n\ntype Loaded =\n  | { base: ContentItem; status: ContentStatus | null; copyOfBuiltIn: boolean }\n  | \"missing\";\n\nexport default function Editor({\n  id,\n  preset,\n  copyOf,\n}: {\n  id: string | null;\n  preset?: { place: PlaceId | null; topic: TopicId | null };\n  /** Duplicate: start a new item from this one */\n  copyOf?: string | null;\n}) {\n  const studio = useStudio();\n  const canPublish = studio.can(\"content.publish\");\n  const fresh = () =>\n    presetFor(blankItem(), preset?.place ?? null, preset?.topic ?? null);\n  const router = useRouter();\n  const showToast = useToast();\n  const repo = getContentRepo();\n\n  const [loaded, setLoaded] = useState<Loaded | null>(\n    id || copyOf ? null : { base: fresh(), status: null, copyOfBuiltIn: false },\n  );\n  const [takenIds, setTakenIds] = useState<Set<string>>(\n    new Set(LIBRARY.map((c) => c.id)),\n  );\n  const [loadError, setLoadError] = useState<string | null>(null);\n\n  const [draft, setDraft] = useState<ContentItem>(blankItem());\n  const [texts, setTexts] = useState<Texts>(textsOf(blankItem()));\n  const [savedJson, setSavedJson] = useState(\"\");\n  const [idTouched, setIdTouched] = useState(false);\n  const [busy, setBusy] = useState<string | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const fileInput = useRef<HTMLInputElement>(null);\n  const videoInput = useRef<HTMLInputElement>(null);\n  const quickVideo = useRef<HTMLInputElement>(null);\n  // Reels get a short form (video, caption, topic). \"More options\" opens the full editor.\n  const [fullForm, setFullForm] = useState(false);\n  const [ytBlocked, setYtBlocked] = useState<string | null>(null);\n  // Big videos are made smaller in the browser before upload (Step 75)\n  const [shrink, setShrink] = useState<{ pct: number; pass: number; mb: number } | null>(null);\n  const shrinkAbort = useRef<AbortController | null>(null);\n  const audioInput = useRef<HTMLInputElement>(null);\n  const [versions, setVersions] = useState<Version[] | null>(null);\n  const [showHistory, setShowHistory] = useState(false);\n  const [confirmDelete, setConfirmDelete] = useState(false);\n\n  // Load: from the database first, otherwise a built-in item to copy\n  useEffect(() => {\n    repo\n      .listAll()\n      .then((all) => {\n        setTakenIds(\n          new Set([...LIBRARY.map((c) => c.id), ...all.map((c) => c.id)]),\n        );\n        const taken = new Set([\n          ...LIBRARY.map((c) => c.id),\n          ...all.map((c) => c.id),\n        ]);\n        if (!id && copyOf) {\n          // Duplicate: same content, new address, saved as a new draft\n          const src =\n            all.find((c) => c.id === copyOf) ??\n            LIBRARY.find((c) => c.id === copyOf);\n          if (!src) return setLoaded(\"missing\");\n          let newId = slugify(src.title + \" copy\");\n          for (let n = 2; taken.has(newId); n++)\n            newId = slugify(src.title + \" copy \" + n);\n          setLoaded({\n            base: {\n              ...src,\n              id: newId,\n              title: src.title + \" (copy)\",\n              status: \"draft\",\n              featured: undefined,\n              publishAt: undefined,\n              reviewNote: undefined,\n              fixture: false,\n              builtIn: false,\n              updatedAt: undefined,\n            },\n            status: null,\n            copyOfBuiltIn: false,\n          });\n          return;\n        }\n        if (!id) return;\n        const mine = all.find((c) => c.id === id);\n        const builtIn = LIBRARY.find((c) => c.id === id);\n        if (mine)\n          setLoaded({\n            base: mine,\n            status: mine.status ?? \"draft\",\n            copyOfBuiltIn: Boolean(builtIn),\n          });\n        else if (builtIn)\n          setLoaded({\n            base: {\n              ...builtIn,\n              fixture: false,\n              builtIn: false,\n              status: \"draft\",\n            },\n            status: null,\n            copyOfBuiltIn: true,\n          });\n        else setLoaded(\"missing\");\n      })\n      .catch((e: Error) => setLoadError(e.message));\n  }, [id, repo, copyOf]);\n\n  useEffect(() => {\n    if (!loaded || loaded === \"missing\") return;\n    setDraft(loaded.base);\n    setTexts(textsOf(loaded.base));\n    // A Kiswahili translation handed over from Admin → AI: filled in, not saved, marked AI-assisted\n    try {\n      const key = `ms_ai_sw:${loaded.base.id}`;\n      const raw = sessionStorage.getItem(key);\n      if (raw) {\n        sessionStorage.removeItem(key);\n        const sw = JSON.parse(raw) as {\n          titleSw?: string;\n          summarySw?: string;\n          bodySw?: string[];\n        };\n        setDraft((d) => ({\n          ...d,\n          titleSw: sw.titleSw || d.titleSw,\n          summarySw: sw.summarySw || d.summarySw,\n          aiGenerated: true,\n        }));\n        if (Array.isArray(sw.bodySw))\n          setTexts((t) => ({ ...t, bodySw: fromParagraphs(sw.bodySw) }));\n        showToast(\"Kiswahili from AI filled in · check it, then save\");\n      }\n    } catch {}\n    setSavedJson(\n      loaded.status\n        ? JSON.stringify(compose(loaded.base, textsOf(loaded.base)))\n        : \"\",\n    );\n  }, [loaded, showToast]);\n\n  // The item as it will be saved\n  const item: ContentItem = useMemo(\n    () => compose(draft, texts),\n    [draft, texts],\n  );\n\n  const status = loaded && loaded !== \"missing\" ? loaded.status : null; // null = not in the database yet\n  const isNew = status === null;\n  const claims = useMemo(() => checkClaims(item), [item]);\n  const problems = useMemo(() => publishProblems(item), [item]);\n  const idTaken =\n    isNew &&\n    !(loaded !== \"missing\" && loaded?.copyOfBuiltIn) &&\n    takenIds.has(item.id);\n  const dirty = JSON.stringify(item) !== savedJson;\n\n  // Warn before leaving with unsaved changes\n  useEffect(() => {\n    if (!dirty) return;\n    const warn = (e: BeforeUnloadEvent) => e.preventDefault();\n    window.addEventListener(\"beforeunload\", warn);\n    return () => window.removeEventListener(\"beforeunload\", warn);\n  }, [dirty]);\n\n  const set = <K extends keyof ContentItem>(key: K, value: ContentItem[K]) =>\n    setDraft((d) => ({ ...d, [key]: value }));\n  const setText = (key: keyof Texts, value: string) =>\n    setTexts((t) => ({ ...t, [key]: value }));\n\n  function setTitle(title: string) {\n    setDraft((d) => ({\n      ...d,\n      title,\n      id: isNew && !idTouched && !loadedCopy() ? slugify(title) : d.id,\n    }));\n  }\n  const loadedCopy = () =>\n    loaded !== null && loaded !== \"missing\" && loaded.copyOfBuiltIn;\n\n  async function save(next: ContentStatus) {\n    setError(null);\n    if (!ID_RULE.test(item.id))\n      return setError(\"Add a title first (it makes the web address).\");\n    if (idTaken)\n      return setError(\n        `The web address \"${item.id}\" is already used. Change it below the title.`,\n      );\n    if ((next === \"published\" || next === \"review\") && problems.length)\n      return setError(\n        next === \"review\"\n          ? \"Not ready for review yet. See the checklist.\"\n          : \"Not ready to publish yet. See the checklist.\",\n      );\n    const scheduled =\n      next === \"published\" &&\n      item.publishAt &&\n      new Date(item.publishAt) > new Date();\n    setBusy(next);\n    try {\n      const saved = await repo.save(item, next);\n      const merged = {\n        ...item,\n        status: saved.status,\n        updatedAt: saved.updatedAt,\n      };\n      setSavedJson(JSON.stringify(merged));\n      setDraft(merged);\n      setLoaded({ base: merged, status: next, copyOfBuiltIn: loadedCopy() });\n      showToast(\n        scheduled\n          ? `Scheduled for ${new Date(item.publishAt!).toLocaleString(\"en-GB\", { day: \"numeric\", month: \"short\", hour: \"2-digit\", minute: \"2-digit\" })}`\n          : next === \"published\"\n            ? status === \"published\"\n              ? \"Live version updated\"\n              : \"Published\"\n            : next === \"review\"\n              ? \"Sent for review\"\n              : next === \"archived\"\n                ? \"Archived\"\n                : \"Draft saved\",\n      );\n      if (isNew)\n        router.replace(`/studio/edit?id=${encodeURIComponent(item.id)}`);\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(null);\n    }\n  }\n\n  async function openHistory() {\n    setShowHistory(true);\n    setVersions(null);\n    try {\n      setVersions(await repo.listVersions(item.id));\n    } catch (e) {\n      setShowHistory(false);\n      setError((e as Error).message);\n    }\n  }\n\n  function loadVersion(v: Version) {\n    // Keeps this item's address; you review the old text, then save or publish it again\n    const restored = {\n      ...v.item,\n      id: item.id,\n      status: item.status,\n      updatedAt: item.updatedAt,\n    };\n    setDraft(restored);\n    setTexts(textsOf(restored));\n    setShowHistory(false);\n    showToast(\"Older version loaded · save to keep it\");\n  }\n\n  async function uploadAudio(file: File | undefined) {\n    if (!file) return;\n    if (!ID_RULE.test(item.id))\n      return setError(\"Add a title first, then the audio.\");\n    setError(null);\n    setBusy(\"audio\");\n    try {\n      set(\"audioUrl\", await repo.uploadAudio(file, item.id));\n      showToast(\"Audio added · save to keep it\");\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(null);\n      if (audioInput.current) audioInput.current.value = \"\";\n    }\n  }\n\n  async function remove() {\n    setConfirmDelete(false);\n    setBusy(\"delete\");\n    try {\n      await repo.remove(item.id);\n      setSavedJson(JSON.stringify(item));\n      showToast(\"Deleted\");\n      router.push(\"/studio/content\");\n    } catch (e) {\n      setError((e as Error).message);\n      setBusy(null);\n    }\n  }\n\n  async function upload(file: File | undefined) {\n    if (!file) return;\n    if (!ID_RULE.test(item.id))\n      return setError(\"Add a title first, then the photo.\");\n    setError(null);\n    setBusy(\"image\");\n    try {\n      set(\"coverImageUrl\", await repo.uploadImage(file, item.id));\n      showToast(\"Photo added · save to keep it\");\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setBusy(null);\n      if (fileInput.current) fileInput.current.value = \"\";\n    }\n  }\n\n  async function uploadVideo(file: File | undefined) {\n    if (!file) return;\n    let vid = item.id;\n    if (!ID_RULE.test(vid)) {\n      if (item.kind !== \"reel\")\n        return setError(\"Add a title first, then the video.\");\n      // A reel can start with the video: it gets its own web address\n      vid = `reel-${Date.now().toString(36)}`;\n      setIdTouched(true);\n      set(\"id\", vid);\n    }\n    setError(null);\n    setBusy(\"video\");\n    try {\n      let toSend = file;\n      if (file.size > MAX_VIDEO_BYTES) {\n        const mb = Math.round(file.size / 1048576);\n        if (!canShrink())\n          throw new Error(`This video is ${mb} MB (the limit is 50 MB). Open the Studio in Chrome to make it smaller here, or shrink it in CapCut (Export → 720p).`);\n        const ac = new AbortController();\n        shrinkAbort.current = ac;\n        setShrink({ pct: 0, pass: 1, mb });\n        let last = -1;\n        toSend = await shrinkVideo(file, {\n          signal: ac.signal,\n          onProgress: (f, pass) => {\n            const pct = Math.floor(f * 100) + pass * 1000;\n            if (pct === last) return;\n            last = pct;\n            setShrink({ pct: f, pass, mb });\n          },\n        });\n        setShrink(null);\n        showToast(`Made smaller: ${mb} MB → ${Math.max(1, Math.round(toSend.size / 1048576))} MB · uploading`);\n      }\n      set(\"videoUrl\", await repo.uploadVideo(toSend, vid));\n      showToast(\"Video added · save to keep it\");\n    } catch (e) {\n      setError((e as Error).message);\n    } finally {\n      setShrink(null);\n      shrinkAbort.current = null;\n      setBusy(null);\n      if (videoInput.current) videoInput.current.value = \"\";\n      if (quickVideo.current) quickVideo.current.value = \"\";\n    }\n  }\n\n  if (loadError) return <Notice title=\"Couldn't load\">{loadError}</Notice>;\n  if (loaded === \"missing\")\n    return (\n      <Notice title=\"Not found\">\n        Nothing with the address &ldquo;{id}&rdquo;.{\" \"}\n        <Link href=\"/studio\" className=\"font-semibold text-forest\">\n          Back to content\n        </Link>\n      </Notice>\n    );\n  if (!loaded)\n    return (\n      <div className=\"flex justify-center py-20 text-ink-soft\">\n        <Loader2 className=\"animate-spin\" />\n      </div>\n    );\n\n  const quick = item.kind === \"reel\" && !fullForm;\n  const yt = youtubeId(item.videoUrl);\n  /** A pasted video link: YouTube links are tidied; a reel gets a web address so the caption can come later. */\n  function pasteVideo(raw: string) {\n    const v = raw.trim();\n    const link = youtubeId(v) ? cleanYouTubeUrl(v)! : v;\n    setYtBlocked(null);\n    setDraft((d) => ({\n      ...d,\n      videoUrl: link || undefined,\n      ...(d.kind === \"reel\" && link && !ID_RULE.test(d.id) ? { id: `reel-${Date.now().toString(36)}` } : {}),\n    }));\n    if (item.kind === \"reel\" && link && !ID_RULE.test(item.id)) setIdTouched(true);\n  }\n  const shrinkNote = shrink ? (\n    <div className=\"space-y-2 rounded-2xl bg-mint/30 p-3 text-sm ring-1 ring-forest/20\" role=\"status\">\n      <p className=\"font-semibold\">\n        Making the video smaller… {Math.round(shrink.pct * 100)}%{shrink.pass > 1 ? \" (second try, a bit smaller)\" : \"\"}\n      </p>\n      <div className=\"h-2 overflow-hidden rounded-full bg-line\">\n        <div className=\"h-full bg-forest transition-[width]\" style={{ width: `${shrink.pct * 100}%` }} />\n      </div>\n      <p className=\"text-xs text-ink-soft\">\n        It&apos;s {shrink.mb} MB, over the 50 MB limit, so it&apos;s being made 720p. This takes about as long as the video itself. Keep this page open and on screen.\n      </p>\n      <button type=\"button\" className={btn.small} onClick={() => shrinkAbort.current?.abort()}>\n        <X size={13} /> Stop\n      </button>\n    </div>\n  ) : null;\n  const ytNote = yt ? (\n    ytBlocked === item.videoUrl ? (\n      <p className=\"text-xs font-semibold text-red-700\">\n        YouTube says this video&apos;s owner doesn&apos;t allow it to play in other apps (or it&apos;s private or removed). Men will see &ldquo;This video can&apos;t play here&rdquo;. Use another video.\n      </p>\n    ) : (\n      <p className=\"text-xs text-ink-soft\">\n        YouTube video · plays inside the app{isYouTubeShort(item.videoUrl) ? \" (Short, upright)\" : \"\"}. YouTube may show its logo, and ads if the channel has them.\n      </p>\n    )\n  ) : null;\n  const caption = item.summary || item.title;\n  /** One caption, written once: the first line is the title, the whole thing the caption, same in both languages. */\n  function setCaption(text: string) {\n    const first = text.split(\"\\n\")[0].trim();\n    const title =\n      first.length > 100 ? first.slice(0, 100).replace(/\\s+\\S*$/, \"\") : first;\n    setDraft((d) => ({\n      ...d,\n      title,\n      titleSw: title || undefined,\n      summary: text,\n      summarySw: text || undefined,\n      inManFeed: false,\n      id: isNew && !idTouched && !loadedCopy() ? slugify(title) : d.id,\n    }));\n  }\n\n  const blocks = claims.filter((c) => c.level === \"block\");\n  const warns = claims.filter((c) => c.level === \"warn\");\n\n  return (\n    <div className=\"space-y-5\">\n      <div className=\"flex flex-wrap items-center justify-between gap-3\">\n        <Link\n          href=\"/studio/content\"\n          className=\"flex items-center gap-1 text-sm text-ink-soft\"\n        >\n          <ArrowLeft size={16} /> All content\n        </Link>\n        <div className=\"flex flex-wrap items-center gap-2\">\n          {status && (\n            <>\n              <button type=\"button\" onClick={openHistory} className={btn.small}>\n                <History size={13} /> History\n              </button>\n              <Link\n                href={`/studio/edit?copy=${encodeURIComponent(item.id)}`}\n                className={btn.small}\n              >\n                <Copy size={13} /> Duplicate\n              </Link>\n            </>\n          )}\n          <span\n            className={`rounded-full px-3 py-1 text-xs font-semibold ring-1 ${status ? STATUS_STYLE[displayStatus({ status, publishAt: loaded.base.publishAt })] : \"bg-bg text-ink-soft ring-line\"}`}\n          >\n            {status\n              ? STATUS_LABEL[\n                  displayStatus({ status, publishAt: loaded.base.publishAt })\n                ]\n              : \"Not saved yet\"}\n            {dirty && status ? \" · unsaved changes\" : \"\"}\n          </span>\n        </div>\n      </div>\n      {status === \"review\" && loaded.base.reviewNote && (\n        <p className=\"rounded-2xl bg-amber-50 px-4 py-3 text-sm text-amber-900\">\n          <b>Review note:</b> {loaded.base.reviewNote}\n        </p>\n      )}\n\n      {loaded.copyOfBuiltIn && (\n        <p className=\"rounded-2xl bg-mint/60 px-4 py-3 text-sm text-forest-deep\">\n          {isNew\n            ? \"You're editing a copy of a built-in item. When you publish it, your version replaces the built-in one in the app.\"\n            : \"This is your edited copy of a built-in item. Published = your version shows in the app.\"}\n        </p>\n      )}\n\n      <div className=\"grid gap-6 lg:grid-cols-[minmax(0,1fr)_360px]\">\n        <div className=\"space-y-5\">\n          {quick ? (\n            <Section title=\"New reel\">\n              <div className=\"flex flex-wrap items-center gap-2 text-xs text-ink-soft\">\n                Making something else?\n                {KINDS.filter((k) => k !== \"reel\")\n                  .slice(0, 3)\n                  .map((k) => (\n                    <button\n                      key={k}\n                      type=\"button\"\n                      onClick={() => set(\"kind\", k)}\n                      className=\"font-semibold text-forest underline\"\n                    >\n                      {KIND_LABEL[k]}\n                    </button>\n                  ))}\n                <button\n                  type=\"button\"\n                  onClick={() => setFullForm(true)}\n                  className=\"font-semibold text-forest underline\"\n                >\n                  More…\n                </button>\n              </div>\n\n              {/* 1. The video */}\n              {item.videoUrl ? (\n                <div className=\"flex items-end gap-3\">\n                  {yt ? (\n                    <YouTubeFrame\n                      id={yt}\n                      controls\n                      title={item.title || \"Reel\"}\n                      onBlocked={() => setYtBlocked(item.videoUrl ?? null)}\n                      className=\"aspect-[9/16] w-36 shrink-0 rounded-2xl\"\n                    />\n                  ) : (\n                    <video\n                      src={item.videoUrl}\n                      controls\n                      playsInline\n                      preload=\"metadata\"\n                      className=\"aspect-[9/16] w-36 shrink-0 rounded-2xl bg-black\"\n                    />\n                  )}\n                  <div className=\"space-y-2\">\n                    <button\n                      type=\"button\"\n                      onClick={() => quickVideo.current?.click()}\n                      disabled={busy === \"video\"}\n                      className={btn.small}\n                    >\n                      {busy === \"video\" ? (\n                        <Loader2 size={13} className=\"animate-spin\" />\n                      ) : (\n                        <Film size={13} />\n                      )}{\" \"}\n                      Change video\n                    </button>\n                  </div>\n                </div>\n              ) : (\n                <button\n                  type=\"button\"\n                  onClick={() => quickVideo.current?.click()}\n                  disabled={busy === \"video\"}\n                  className=\"flex w-full flex-col items-center justify-center gap-2 rounded-3xl border-2 border-dashed border-forest/40 bg-mint/20 py-10 text-forest disabled:opacity-60\"\n                >\n                  {busy === \"video\" ? (\n                    <Loader2 size={28} className=\"animate-spin\" />\n                  ) : (\n                    <Film size={28} />\n                  )}\n                  <span className=\"font-bold\">\n                    {busy === \"video\" ? (shrink ? \"Making it smaller…\" : \"Uploading…\") : \"Choose the video\"}\n                  </span>\n                  <span className=\"text-xs text-ink-soft\">\n                    Upright. Big videos are made smaller for you.\n                  </span>\n                </button>\n              )}\n              <input\n                ref={quickVideo}\n                type=\"file\"\n                accept=\"video/mp4,video/webm,video/quicktime\"\n                className=\"hidden\"\n                onChange={(e) => uploadVideo(e.target.files?.[0])}\n              />\n              <Field label=\"Or paste a YouTube link\" hint=\"A Short or any YouTube video. It plays inside the app, no upload needed.\">\n                <input\n                  className={input}\n                  type=\"url\"\n                  inputMode=\"url\"\n                  placeholder=\"https://youtube.com/shorts/…\"\n                  value={item.videoUrl && !item.videoUrl.includes(\"supabase.co\") ? item.videoUrl : \"\"}\n                  onChange={(e) => pasteVideo(e.target.value)}\n                />\n              </Field>\n              {shrinkNote}\n              {ytNote}\n\n              {/* 2. The caption */}\n              <Field\n                label=\"Caption\"\n                hint=\"Write it once, in Kiswahili or English. The first line is the title.\"\n              >\n                <textarea\n                  className={`${input} min-h-24`}\n                  value={caption}\n                  onChange={(e) => setCaption(e.target.value)}\n                  placeholder=\"e.g. Mchanganyiko wa vitunguu saumu, tangawizi na manjano\"\n                  maxLength={600}\n                />\n              </Field>\n\n              {/* 3. Where men find it: the same circles they tap at the top of Discover (Step 80) */}\n              <Field group label=\"Circle on Discover\" hint=\"The circles men tap at the top of Discover. Pick one or more.\">\n                <CirclePicker item={item} onChange={(c, noTopic) => setDraft((d) => setCircles(d, c, noTopic))} />\n              </Field>\n\n              {(problems.length > 0 || blocks.length > 0) &&\n                (item.videoUrl || caption) && (\n                  <ul className=\"space-y-1 rounded-2xl bg-amber-50 px-4 py-3 text-xs text-amber-900\">\n                    {problems.map((p) => (\n                      <li key={p}>• {p}</li>\n                    ))}\n                  </ul>\n                )}\n              <button\n                type=\"button\"\n                onClick={() => setFullForm(true)}\n                className=\"text-xs font-semibold text-ink-soft underline\"\n              >\n                More options (cover photo, schedule, separate Kiswahili text…)\n              </button>\n            </Section>\n          ) : (\n            <>\n              {/* Basics */}\n              <Section title=\"What is it?\">\n                <div className=\"flex flex-wrap gap-2\">\n                  {KINDS.map((k) => (\n                    <Chip\n                      key={k}\n                      on={item.kind === k}\n                      onClick={() => set(\"kind\", k)}\n                    >\n                      {KIND_LABEL[k]}\n                    </Chip>\n                  ))}\n                </div>\n                <Field group label=\"Circle on Discover\" hint=\"The circles men tap at the top of Discover. Pick one or more.\">\n                  <CirclePicker item={item} onChange={(c, noTopic) => setDraft((d) => setCircles(d, c, noTopic))} />\n                </Field>\n              </Section>\n\n              <Section title=\"Title and summary\">\n                <Field label=\"Title (English)\">\n                  <input\n                    className={input}\n                    value={item.title}\n                    onChange={(e) => setTitle(e.target.value)}\n                    placeholder=\"e.g. Why sleep matters for erections\"\n                    maxLength={160}\n                  />\n                </Field>\n                <Field\n                  label=\"Web address\"\n                  hint={\n                    isNew && !loaded.copyOfBuiltIn\n                      ? \"Made from the title. Can't change after the first save.\"\n                      : \"Fixed after the first save.\"\n                  }\n                >\n                  <input\n                    className={`${input} font-mono text-xs`}\n                    value={item.id}\n                    disabled={!isNew || loaded.copyOfBuiltIn}\n                    onChange={(e) => {\n                      setIdTouched(true);\n                      set(\n                        \"id\",\n                        e.target.value\n                          .toLowerCase()\n                          .replace(/[^a-z0-9-]/g, \"-\"),\n                      );\n                    }}\n                  />\n                  {idTaken && (\n                    <p className=\"mt-1 text-xs text-red-700\">\n                      Already used. Change it a little, e.g. add\n                      &ldquo;-2&rdquo;.\n                    </p>\n                  )}\n                </Field>\n                <Field\n                  label=\"Title (Kiswahili)\"\n                  hint=\"Optional, but needed if you add Kiswahili text.\"\n                >\n                  <input\n                    className={input}\n                    value={item.titleSw ?? \"\"}\n                    onChange={(e) =>\n                      set(\"titleSw\", e.target.value || undefined)\n                    }\n                    maxLength={160}\n                  />\n                </Field>\n                <Field\n                  label=\"Summary\"\n                  hint=\"What he gains from it, in one or two short sentences.\"\n                >\n                  <textarea\n                    className={`${input} min-h-20`}\n                    value={item.summary}\n                    onChange={(e) => set(\"summary\", e.target.value)}\n                  />\n                </Field>\n                <Field\n                  label=\"Summary (Kiswahili)\"\n                  hint=\"Optional. Shown when a man uses the app in Kiswahili.\"\n                >\n                  <textarea\n                    lang=\"sw\"\n                    className={`${input} min-h-20`}\n                    value={item.summarySw ?? \"\"}\n                    onChange={(e) =>\n                      set(\"summarySw\", e.target.value || undefined)\n                    }\n                  />\n                </Field>\n              </Section>\n\n              {/* Content by type */}\n              <Section\n                title={\n                  item.kind === \"expert\"\n                    ? \"Question and answer\"\n                    : item.kind === \"video\"\n                      ? \"Video\"\n                      : item.kind === \"reel\"\n                        ? \"Reel (vertical video)\"\n                        : item.kind === \"audio\"\n                          ? \"Audio\"\n                          : item.kind === \"infographic\"\n                            ? \"Infographic\"\n                            : item.kind === \"quiz\"\n                              ? \"Quiz\"\n                              : \"Text\"\n                }\n              >\n                {item.kind === \"expert\" && (\n                  <Field label=\"The question a man asked\">\n                    <textarea\n                      className={`${input} min-h-16`}\n                      value={item.question ?? \"\"}\n                      onChange={(e) =>\n                        set(\"question\", e.target.value || undefined)\n                      }\n                    />\n                  </Field>\n                )}\n                {item.kind === \"infographic\" && (\n                  <p className=\"rounded-2xl bg-mint/60 px-4 py-3 text-xs text-forest-deep\">\n                    The infographic is the <b>cover photo</b> (upload it under\n                    Cover below). It&apos;s shown full size on the page; the\n                    text underneath is optional.\n                  </p>\n                )}\n                {item.kind === \"audio\" && (\n                  <div className=\"space-y-3\">\n                    {item.audioUrl && (\n                      <audio\n                        src={item.audioUrl}\n                        controls\n                        preload=\"metadata\"\n                        className=\"w-full\"\n                      />\n                    )}\n                    <div className=\"flex flex-wrap items-center gap-3\">\n                      <button\n                        type=\"button\"\n                        onClick={() => audioInput.current?.click()}\n                        disabled={busy === \"audio\"}\n                        className=\"flex items-center gap-2 rounded-full bg-forest px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60\"\n                      >\n                        {busy === \"audio\" ? (\n                          <Loader2 size={16} className=\"animate-spin\" />\n                        ) : (\n                          <Mic size={16} />\n                        )}\n                        {busy === \"audio\"\n                          ? shrink\n                            ? \"Making it smaller…\"\n                            : \"Uploading…\"\n                          : item.audioUrl\n                            ? \"Change audio\"\n                            : \"Upload audio\"}\n                      </button>\n                      {item.audioUrl && (\n                        <button\n                          type=\"button\"\n                          onClick={() => set(\"audioUrl\", undefined)}\n                          className=\"flex items-center gap-1 text-sm font-semibold text-ink-soft\"\n                        >\n                          <X size={14} /> Remove audio\n                        </button>\n                      )}\n                      <input\n                        ref={audioInput}\n                        type=\"file\"\n                        accept=\"audio/*\"\n                        className=\"hidden\"\n                        onChange={(e) => uploadAudio(e.target.files?.[0])}\n                      />\n                      <span className=\"text-xs text-ink-soft\">\n                        MP3, M4A, AAC, OGG or WAV, under 40 MB.\n                      </span>\n                    </div>\n                    <Field\n                      label=\"Or paste an audio link\"\n                      hint=\"A direct https link to an .mp3 or .m4a file.\"\n                    >\n                      <input\n                        className={input}\n                        type=\"url\"\n                        placeholder=\"https://…/episode.mp3\"\n                        value={item.audioUrl ?? \"\"}\n                        onChange={(e) =>\n                          set(\"audioUrl\", e.target.value.trim() || undefined)\n                        }\n                      />\n                    </Field>\n                    <Field\n                      label=\"Key points\"\n                      hint=\"One per line. Shown under the player.\"\n                    >\n                      <textarea\n                        className={`${input} min-h-28`}\n                        value={texts.keyPoints}\n                        onChange={(e) => setText(\"keyPoints\", e.target.value)}\n                      />\n                    </Field>\n                  </div>\n                )}\n                {item.kind === \"reel\" && (\n                  <p className=\"rounded-2xl bg-mint/60 px-4 py-3 text-xs text-forest-deep\">\n                    A reel is a <b>vertical video</b> (filmed upright on a\n                    phone, 9:16), best under 90 seconds. It shows in the Reels\n                    row on Discover and in the feed, and plays full screen. The\n                    title and summary are its caption. A cover photo is optional\n                    (the first frame is used).\n                  </p>\n                )}\n                {(item.kind === \"video\" || item.kind === \"reel\") && (\n                  <div className=\"space-y-3\">\n                    {item.videoUrl && yt && (\n                      <YouTubeFrame\n                        id={yt}\n                        controls\n                        title={item.title || \"Video\"}\n                        onBlocked={() => setYtBlocked(item.videoUrl ?? null)}\n                        className={\n                          item.kind === \"reel\" || isYouTubeShort(item.videoUrl)\n                            ? \"mx-auto aspect-[9/16] max-h-[28rem] w-full max-w-[16rem] rounded-2xl\"\n                            : \"aspect-video w-full rounded-2xl\"\n                        }\n                      />\n                    )}\n                    {item.videoUrl && !yt && (\n                      <video\n                        src={item.videoUrl}\n                        controls\n                        playsInline\n                        preload=\"metadata\"\n                        className={\n                          item.kind === \"reel\"\n                            ? \"mx-auto aspect-[9/16] max-h-[28rem] rounded-2xl bg-black\"\n                            : \"aspect-video w-full rounded-2xl bg-black\"\n                        }\n                      />\n                    )}\n                    <div className=\"flex flex-wrap items-center gap-3\">\n                      <button\n                        type=\"button\"\n                        onClick={() => videoInput.current?.click()}\n                        disabled={busy === \"video\"}\n                        className=\"flex items-center gap-2 rounded-full bg-forest px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60\"\n                      >\n                        {busy === \"video\" ? (\n                          <Loader2 size={16} className=\"animate-spin\" />\n                        ) : (\n                          <Film size={16} />\n                        )}\n                        {busy === \"video\"\n                          ? shrink\n                            ? \"Making it smaller…\"\n                            : \"Uploading…\"\n                          : item.videoUrl\n                            ? \"Change video\"\n                            : \"Upload video\"}\n                      </button>\n                      {item.videoUrl && (\n                        <button\n                          type=\"button\"\n                          onClick={() => set(\"videoUrl\", undefined)}\n                          className=\"flex items-center gap-1 text-sm font-semibold text-ink-soft\"\n                        >\n                          <X size={14} /> Remove video\n                        </button>\n                      )}\n                      <input\n                        ref={videoInput}\n                        type=\"file\"\n                        accept=\"video/mp4,video/webm,video/quicktime\"\n                        className=\"hidden\"\n                        onChange={(e) => uploadVideo(e.target.files?.[0])}\n                      />\n                      <span className=\"text-xs text-ink-soft\">\n                        {item.kind === \"reel\"\n                          ? \"MP4 or MOV, upright. Over 50 MB is made smaller for you (Chrome). Best under 90 seconds.\"\n                          : \"MP4, WebM or MOV. Over 50 MB is made smaller for you (Chrome). Short is best: 2 minutes or less.\"}\n                      </span>\n                    </div>\n                    <Field\n                      label=\"Or paste a video link\"\n                      hint=\"A YouTube link (plays inside the app) or a direct https link to an .mp4 file. Instagram links go in the post's origin, not here.\"\n                    >\n                      <input\n                        className={input}\n                        type=\"url\"\n                        placeholder=\"https://youtube.com/watch?v=… or https://…/video.mp4\"\n                        value={item.videoUrl ?? \"\"}\n                        onChange={(e) => pasteVideo(e.target.value)}\n                      />\n                    </Field>\n                    {shrinkNote}\n                    {ytNote}\n                  </div>\n                )}\n                {item.kind === \"video\" && (\n                  <Field\n                    label=\"Key points\"\n                    hint=\"One per line. Shown under the video.\"\n                  >\n                    <textarea\n                      className={`${input} min-h-28`}\n                      value={texts.keyPoints}\n                      onChange={(e) => setText(\"keyPoints\", e.target.value)}\n                    />\n                  </Field>\n                )}\n                {item.kind === \"quiz\" && (\n                  <QuizEditor\n                    value={item.quiz ?? []}\n                    onChange={(q) => set(\"quiz\", q)}\n                  />\n                )}\n                {item.kind === \"tool\" && (\n                  <Field group label=\"Which tool\">\n                    <div className=\"flex flex-wrap gap-2\">\n                      {TOOLS.map((t) => (\n                        <Chip\n                          key={t.id}\n                          on={item.tool === t.id}\n                          onClick={() => set(\"tool\", t.id)}\n                        >\n                          {t.label}\n                        </Chip>\n                      ))}\n                    </div>\n                  </Field>\n                )}\n                <Field\n                  label={\n                    item.kind === \"expert\"\n                      ? \"Answer (English)\"\n                      : \"Text (English)\"\n                  }\n                  hint='Leave an empty line between paragraphs. Start a line with \"## \" to make a heading.'\n                >\n                  <textarea\n                    className={`${input} min-h-56 leading-relaxed`}\n                    value={texts.body}\n                    onChange={(e) => setText(\"body\", e.target.value)}\n                  />\n                </Field>\n                <Field\n                  label=\"Text (Kiswahili)\"\n                  hint=\"Optional. Readers can switch language on the page.\"\n                >\n                  <textarea\n                    lang=\"sw\"\n                    className={`${input} min-h-40 leading-relaxed`}\n                    value={texts.bodySw}\n                    onChange={(e) => setText(\"bodySw\", e.target.value)}\n                  />\n                </Field>\n              </Section>\n\n              {/* Where men see it */}\n              <Section title=\"Where it shows\">\n                <ul className=\"flex flex-wrap gap-2\">\n                  {placesOf(item).map((p) => (\n                    <li\n                      key={p.id}\n                      className=\"flex items-center gap-1 rounded-full bg-mint/70 px-3 py-1.5 text-xs font-semibold text-forest-deep\"\n                    >\n                      <MapPin size={12} />\n                      {p.id === \"library\"\n                        ? `Library · ${TOPICS.find((t) => t.id === item.topic)?.title ?? \"no topic\"}`\n                        : p.title}\n                    </li>\n                  ))}\n                </ul>\n                <p className=\"text-xs text-ink-soft\">\n                  {item.kind === \"reel\"\n                    ? \"Reels show in the Reels row and between the cards on Discover. To put this one first for everyone, pin it in \"\n                    : \"Discover now shows reels and “do this” cards. Guides, articles and videos reach men through search, Saved, Kito, topic pages and links. To pin or hide things on Discover, use \"}\n                  <Link\n                    href=\"/studio/discover\"\n                    className=\"font-semibold text-forest underline\"\n                  >\n                    Studio → Discover\n                  </Link>\n                  .\n                </p>\n                <label className=\"flex items-start gap-3 text-sm\">\n                  <input\n                    type=\"checkbox\"\n                    className=\"mt-1 accent-forest\"\n                    checked={Boolean(item.inManFeed)}\n                    onChange={(e) => set(\"inManFeed\", e.target.checked)}\n                  />\n                  <span>\n                    <b>Show as a daily lesson on the Man tab</b>\n                    <span className=\"block text-xs text-ink-soft\">\n                      He earns the points below when he marks it as read.\n                    </span>\n                  </span>\n                </label>\n              </Section>\n\n              {/* Publishing: schedule, review, AI */}\n              <Section title=\"Publishing\">\n                <Field\n                  label=\"Go live at (optional)\"\n                  hint={\n                    item.publishAt && new Date(item.publishAt) > new Date()\n                      ? \"Scheduled: men see it from this time. Leave empty to go live as soon as it's published.\"\n                      : \"Leave empty to go live as soon as it's published. Pick a future time to schedule it.\"\n                  }\n                >\n                  <div className=\"flex flex-wrap items-center gap-2\">\n                    <input\n                      type=\"datetime-local\"\n                      className={`${input} max-w-xs`}\n                      value={item.publishAt ? toLocalInput(item.publishAt) : \"\"}\n                      onChange={(e) =>\n                        set(\n                          \"publishAt\",\n                          e.target.value\n                            ? new Date(e.target.value).toISOString()\n                            : undefined,\n                        )\n                      }\n                    />\n                    {item.publishAt && (\n                      <button\n                        type=\"button\"\n                        onClick={() => set(\"publishAt\", undefined)}\n                        className=\"text-xs font-semibold text-ink-soft\"\n                      >\n                        Clear\n                      </button>\n                    )}\n                  </div>\n                </Field>\n                <Field\n                  label=\"Note for review (optional)\"\n                  hint=\"What the writer or editor should know. Shown at the top while it's in review.\"\n                >\n                  <textarea\n                    className={`${input} min-h-16`}\n                    maxLength={500}\n                    value={item.reviewNote ?? \"\"}\n                    onChange={(e) =>\n                      set(\"reviewNote\", e.target.value || undefined)\n                    }\n                  />\n                </Field>\n                <label className=\"flex items-start gap-3 text-sm\">\n                  <input\n                    type=\"checkbox\"\n                    className=\"mt-1 accent-forest\"\n                    checked={Boolean(item.aiGenerated)}\n                    onChange={(e) =>\n                      set(\"aiGenerated\", e.target.checked || undefined)\n                    }\n                  />\n                  <span>\n                    <b>Drafted with AI help</b>\n                    <span className=\"block text-xs text-ink-soft\">\n                      For your records only. Staff can publish it straight away.\n                    </span>\n                  </span>\n                </label>\n              </Section>\n\n              {/* Look */}\n              <Section title=\"Cover\">\n                <div className=\"flex flex-wrap items-center gap-3\">\n                  <button\n                    type=\"button\"\n                    onClick={() => fileInput.current?.click()}\n                    disabled={busy === \"image\"}\n                    className=\"flex items-center gap-2 rounded-full bg-forest px-4 py-2.5 text-sm font-semibold text-white disabled:opacity-60\"\n                  >\n                    {busy === \"image\" ? (\n                      <Loader2 size={16} className=\"animate-spin\" />\n                    ) : (\n                      <ImagePlus size={16} />\n                    )}\n                    {item.coverImageUrl ? \"Change photo\" : \"Upload photo\"}\n                  </button>\n                  {item.coverImageUrl && (\n                    <button\n                      type=\"button\"\n                      onClick={() => set(\"coverImageUrl\", undefined)}\n                      className=\"flex items-center gap-1 text-sm font-semibold text-ink-soft\"\n                    >\n                      <X size={14} /> Remove photo\n                    </button>\n                  )}\n                  <input\n                    ref={fileInput}\n                    type=\"file\"\n                    accept=\"image/jpeg,image/png,image/webp\"\n                    className=\"hidden\"\n                    onChange={(e) => upload(e.target.files?.[0])}\n                  />\n                  <span className=\"text-xs text-ink-soft\">\n                    JPG, PNG or WebP, under 3 MB. No intimate photos.\n                  </span>\n                </div>\n                {!item.coverImageUrl && (\n                  <Field group label=\"Or a drawn cover\">\n                    <div className=\"flex flex-wrap items-center gap-2\">\n                      {TONES.map((t) => (\n                        <button\n                          key={t}\n                          type=\"button\"\n                          aria-label={t}\n                          aria-pressed={item.cover.tone === t}\n                          onClick={() =>\n                            set(\"cover\", { ...item.cover, tone: t })\n                          }\n                          className={`h-8 w-8 rounded-full ring-1 ring-line ${item.cover.tone === t ? \"outline-2 outline-offset-2 outline-forest\" : \"\"}`}\n                          style={{ background: TONE_SWATCH[t] }}\n                        />\n                      ))}\n                      <span className=\"mx-1 h-6 w-px bg-line\" />\n                      {MOTIFS.map((m) => (\n                        <Chip\n                          key={m}\n                          on={item.cover.motif === m}\n                          onClick={() =>\n                            set(\"cover\", { ...item.cover, motif: m })\n                          }\n                        >\n                          {m[0].toUpperCase() + m.slice(1)}\n                        </Chip>\n                      ))}\n                    </div>\n                  </Field>\n                )}\n              </Section>\n\n              {/* Details */}\n              <Section title=\"Details\">\n                <div className=\"grid gap-4 sm:grid-cols-3\">\n                  <Field label=\"Minutes to read\">\n                    <input\n                      type=\"number\"\n                      min={1}\n                      max={60}\n                      className={input}\n                      value={item.minutes}\n                      onChange={(e) =>\n                        set(\"minutes\", clamp(e.target.value, 1, 60, 3))\n                      }\n                    />\n                  </Field>\n                  <Field\n                    label=\"Priority (0–100)\"\n                    hint=\"Higher comes first in search, topic pages and the Man tab.\"\n                  >\n                    <input\n                      type=\"number\"\n                      min={0}\n                      max={100}\n                      className={input}\n                      value={item.priority}\n                      onChange={(e) =>\n                        set(\"priority\", clamp(e.target.value, 0, 100, 50))\n                      }\n                    />\n                  </Field>\n                  <Field label=\"Points\">\n                    <input\n                      type=\"number\"\n                      min={0}\n                      max={100}\n                      className={input}\n                      value={item.points ?? 10}\n                      onChange={(e) =>\n                        set(\"points\", clamp(e.target.value, 0, 100, 10))\n                      }\n                    />\n                  </Field>\n                </div>\n                <Field\n                  label=\"Tags\"\n                  hint=\"Separate with commas. Helps search, e.g. sleep, energy, usingizi\"\n                >\n                  <input\n                    className={input}\n                    value={texts.tags}\n                    onChange={(e) => setText(\"tags\", e.target.value)}\n                  />\n                </Field>\n                <Field\n                  label=\"Source\"\n                  hint=\"Shown to readers: who wrote it and where facts come from.\"\n                >\n                  <input\n                    className={input}\n                    value={item.source}\n                    onChange={(e) => set(\"source\", e.target.value)}\n                  />\n                </Field>\n              </Section>\n            </>\n          )}\n        </div>\n\n        {/* Right side: checks and preview */}\n        <aside className=\"space-y-5\">\n          <div\n            className={`space-y-3 rounded-3xl bg-surface p-5 ring-1 ring-line ${quick ? \"hidden\" : \"\"}`}\n          >\n            <p className=\"font-bold\">Claim check</p>\n            {claims.length === 0 ? (\n              <p className=\"flex items-center gap-2 text-sm text-forest\">\n                <CheckCircle2 size={16} /> No selling, promises or contact\n                details found.\n              </p>\n            ) : (\n              <ul className=\"space-y-2\">\n                {[...blocks, ...warns].map((c, i) => (\n                  <li\n                    key={i}\n                    className={`flex gap-2 rounded-2xl px-3 py-2 text-xs ${c.level === \"block\" ? \"bg-red-50 text-red-800\" : \"bg-amber-50 text-amber-900\"}`}\n                  >\n                    {c.level === \"block\" ? (\n                      <OctagonX size={14} className=\"mt-px shrink-0\" />\n                    ) : (\n                      <AlertTriangle size={14} className=\"mt-px shrink-0\" />\n                    )}\n                    <span>\n                      <b>&ldquo;{c.match}&rdquo;</b> · {c.message}\n                    </span>\n                  </li>\n                ))}\n              </ul>\n            )}\n            <p className=\"pt-1 font-bold\">Ready to publish?</p>\n            {problems.length === 0 ? (\n              <p className=\"flex items-center gap-2 text-sm text-forest\">\n                <CheckCircle2 size={16} /> Yes, everything needed is there.\n              </p>\n            ) : (\n              <ul className=\"list-disc space-y-1 pl-5 text-xs text-ink-soft\">\n                {problems.map((p) => (\n                  <li key={p}>{p}</li>\n                ))}\n              </ul>\n            )}\n          </div>\n          <Preview item={item} />\n        </aside>\n      </div>\n\n      {/* Actions: stick to the bottom of the editor while scrolling */}\n      <div className=\"sticky bottom-0 z-20 -mx-4 border-t border-line bg-surface/95 px-4 py-3 backdrop-blur sm:-mx-6 sm:px-6 lg:-mx-8 lg:px-8\">\n        <div className=\"flex flex-wrap items-center gap-2\">\n          {error ? (\n            <p role=\"alert\" className=\"mr-auto max-w-md text-sm text-red-700\">\n              {error}\n            </p>\n          ) : (\n            <p className=\"mr-auto hidden text-xs text-ink-soft sm:block\">\n              {status === \"published\"\n                ? item.publishAt && new Date(item.publishAt) > new Date()\n                  ? \"Scheduled. Men see it from the time you set.\"\n                  : \"Men can see this now.\"\n                : status === \"review\"\n                  ? canPublish\n                    ? \"Waiting for your review.\"\n                    : \"Waiting for an editor to review.\"\n                  : canPublish\n                    ? \"Only staff can see drafts.\"\n                    : \"Writers submit for review; an editor publishes.\"}\n            </p>\n          )}\n          {status &&\n            status !== \"published\" &&\n            (canPublish || status !== \"archived\") && (\n              <button\n                onClick={() => setConfirmDelete(true)}\n                disabled={!!busy}\n                className={ghost}\n              >\n                <Trash2 size={14} /> Delete\n              </button>\n            )}\n          {status === \"published\" && canPublish && (\n            <>\n              <button\n                onClick={() => save(\"archived\")}\n                disabled={!!busy}\n                className={ghost}\n              >\n                <Archive size={14} /> Archive\n              </button>\n              <button\n                onClick={() => save(\"draft\")}\n                disabled={!!busy}\n                className={ghost}\n              >\n                Unpublish\n              </button>\n            </>\n          )}\n          {status !== \"published\" && (\n            <button\n              onClick={() => save(\"draft\")}\n              disabled={!!busy || (!dirty && status === \"draft\")}\n              className={ghost}\n            >\n              {busy === \"draft\" && (\n                <Loader2 size={14} className=\"animate-spin\" />\n              )}\n              {status === \"archived\"\n                ? \"Restore as draft\"\n                : status === \"review\"\n                  ? \"Back to draft\"\n                  : \"Save draft\"}\n            </button>\n          )}\n          {!canPublish &&\n            status !== \"published\" &&\n            status !== \"archived\" &&\n            (status !== \"review\" || dirty) && (\n              <button\n                onClick={() => save(\"review\")}\n                disabled={!!busy || problems.length > 0}\n                className={canPublish ? ghost : primaryBtn}\n              >\n                {busy === \"review\" && (\n                  <Loader2 size={14} className=\"animate-spin\" />\n                )}\n                {status === \"review\"\n                  ? \"Save review changes\"\n                  : \"Submit for review\"}\n              </button>\n            )}\n          {canPublish ? (\n            <button\n              onClick={() => save(\"published\")}\n              disabled={\n                !!busy ||\n                problems.length > 0 ||\n                (status === \"published\" && !dirty)\n              }\n              className={primaryBtn}\n            >\n              {busy === \"published\" && (\n                <Loader2 size={14} className=\"animate-spin\" />\n              )}\n              {item.publishAt && new Date(item.publishAt) > new Date()\n                ? status === \"published\"\n                  ? \"Update schedule\"\n                  : \"Schedule\"\n                : status === \"published\"\n                  ? \"Update live version\"\n                  : \"Publish\"}\n            </button>\n          ) : (\n            status === \"published\" && (\n              <p className=\"text-xs text-ink-soft\">\n                Live content can only be changed by an editor or owner.\n              </p>\n            )\n          )}\n        </div>\n      </div>\n\n      <Confirm\n        open={confirmDelete}\n        title={`Delete \"${item.title}\"?`}\n        confirmLabel=\"Delete for good\"\n        danger\n        typeToConfirm=\"delete\"\n        onConfirm={remove}\n        onClose={() => setConfirmDelete(false)}\n      >\n        It&apos;s removed from the Studio\n        {status === \"published\" ? \" and from the app\" : \"\"}. This can&apos;t be\n        undone. Earlier versions are deleted too. To keep it out of the app but\n        keep a copy, use Archive instead.\n      </Confirm>\n\n      <Drawer\n        open={showHistory}\n        title=\"Version history\"\n        onClose={() => setShowHistory(false)}\n      >\n        {versions === null ? (\n          <p className=\"flex items-center gap-2 text-sm text-ink-soft\">\n            <Loader2 size={16} className=\"animate-spin\" /> Loading…\n          </p>\n        ) : versions.length === 0 ? (\n          <p className=\"text-sm text-ink-soft\">\n            No earlier versions yet. Each time you save a change, the previous\n            version is kept here (the last 30).\n          </p>\n        ) : (\n          <ul className=\"space-y-2\">\n            {versions.map((v) => (\n              <li key={v.id} className=\"rounded-xl p-3 ring-1 ring-line\">\n                <div className=\"flex items-start justify-between gap-2\">\n                  <div className=\"min-w-0\">\n                    <p className=\"truncate text-sm font-semibold\">\n                      {v.item.title}\n                    </p>\n                    <p className=\"text-[0.6875rem] text-ink-soft\">\n                      <Clock size={11} className=\"mr-1 inline\" />\n                      {new Date(v.savedAt).toLocaleString(\"en-GB\", {\n                        day: \"numeric\",\n                        month: \"short\",\n                        hour: \"2-digit\",\n                        minute: \"2-digit\",\n                      })}{\" \"}\n                      · was {v.status}\n                    </p>\n                    <p className=\"mt-1 line-clamp-2 text-xs text-ink-soft\">\n                      {v.item.summary}\n                    </p>\n                  </div>\n                  <button onClick={() => loadVersion(v)} className={btn.small}>\n                    Load\n                  </button>\n                </div>\n              </li>\n            ))}\n          </ul>\n        )}\n      </Drawer>\n    </div>\n  );\n}\n\nfunction QuizEditor({\n  value,\n  onChange,\n}: {\n  value: QuizQuestion[];\n  onChange: (q: QuizQuestion[]) => void;\n}) {\n  const update = (i: number, patch: Partial<QuizQuestion>) =>\n    onChange(value.map((q, j) => (j === i ? { ...q, ...patch } : q)));\n  return (\n    <div className=\"space-y-4\">\n      {value.map((q, i) => (\n        <div\n          key={i}\n          className=\"space-y-3 rounded-2xl bg-bg p-4 ring-1 ring-line\"\n        >\n          <div className=\"flex items-center justify-between\">\n            <p className=\"text-xs font-bold text-ink-soft\">Question {i + 1}</p>\n            <button\n              type=\"button\"\n              onClick={() => onChange(value.filter((_, j) => j !== i))}\n              className=\"text-xs font-semibold text-ink-soft\"\n            >\n              Remove\n            </button>\n          </div>\n          <input\n            className={input}\n            placeholder=\"Question\"\n            value={q.q}\n            onChange={(e) => update(i, { q: e.target.value })}\n          />\n          {q.options.map((o, oi) => (\n            <label key={oi} className=\"flex items-center gap-2\">\n              <input\n                type=\"radio\"\n                name={`answer-${i}`}\n                className=\"accent-forest\"\n                checked={q.answer === oi}\n                onChange={() => update(i, { answer: oi })}\n                aria-label=\"Correct answer\"\n              />\n              <input\n                className={input}\n                placeholder={`Answer ${oi + 1}`}\n                value={o}\n                onChange={(e) =>\n                  update(i, {\n                    options: q.options.map((x, xi) =>\n                      xi === oi ? e.target.value : x,\n                    ),\n                  })\n                }\n              />\n            </label>\n          ))}\n          <p className=\"text-[0.6875rem] text-ink-soft\">\n            Tick the circle next to the correct answer.\n          </p>\n          <input\n            className={input}\n            placeholder=\"Why this is the answer (shown after he answers)\"\n            value={q.explain}\n            onChange={(e) => update(i, { explain: e.target.value })}\n          />\n        </div>\n      ))}\n      <button\n        type=\"button\"\n        onClick={() =>\n          onChange([\n            ...value,\n            { q: \"\", options: [\"\", \"\", \"\"], answer: 0, explain: \"\" },\n          ])\n        }\n        className=\"flex items-center gap-1.5 rounded-full px-4 py-2 text-sm font-semibold text-forest ring-1 ring-line\"\n      >\n        <Plus size={14} /> Add question\n      </button>\n    </div>\n  );\n}\n\nfunction Section({\n  title,\n  children,\n}: {\n  title: string;\n  children: React.ReactNode;\n}) {\n  return (\n    <section className=\"space-y-4 rounded-3xl bg-surface p-5 ring-1 ring-line\">\n      <h2 className=\"font-bold\">{title}</h2>\n      {children}\n    </section>\n  );\n}\n\n/** A labelled field. `group` is for rows of buttons (a <label> would make clicks on the text press the first button). */\nfunction Field({\n  label,\n  hint,\n  group,\n  children,\n}: {\n  label: string;\n  hint?: string;\n  group?: boolean;\n  children: React.ReactNode;\n}) {\n  const Tag = group ? \"div\" : \"label\";\n  return (\n    <Tag className=\"block\">\n      <span className=\"text-xs font-semibold text-ink-soft\">{label}</span>\n      <div className=\"mt-1\">{children}</div>\n      {hint && (\n        <span className=\"mt-1 block text-[0.6875rem] text-ink-soft\">\n          {hint}\n        </span>\n      )}\n    </Tag>\n  );\n}\n\n/** The Discover circles, as staff pick them for a piece of content (Step 80). */\nfunction CirclePicker({ item, onChange }: { item: ContentItem; onChange: (circles: ChallengeId[], noCircleTopic?: TopicId) => void }) {\n  const on = circlesOf({ ...item, action: actionOf(item) });\n  const btn = (active: boolean) =>\n    `rounded-full px-3 py-1.5 text-xs font-semibold ring-1 ${active ? \"bg-forest text-white ring-forest\" : \"ring-line\"}`;\n  return (\n    <div className=\"space-y-2\">\n      <div className=\"flex flex-wrap gap-1.5\">\n        {CIRCLES.map((c) => {\n          const active = on.includes(c.id);\n          return (\n            <button\n              key={c.id}\n              type=\"button\"\n              aria-pressed={active}\n              onClick={() => onChange(active ? on.filter((x) => x !== c.id) : [...on, c.id])}\n              className={btn(active)}\n            >\n              {c.label}\n            </button>\n          );\n        })}\n      </div>\n      <div className=\"flex flex-wrap items-center gap-1.5\">\n        <span className=\"text-[0.6875rem] text-ink-soft\">Fits no circle (shows in For you):</span>\n        {NO_CIRCLE.map((n) => {\n          const active = on.length === 0 && item.topic === n.topic;\n          return (\n            <button key={n.topic} type=\"button\" aria-pressed={active} onClick={() => onChange([], n.topic)} className={btn(active)}>\n              {n.label}\n            </button>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n\nfunction Chip({\n  on,\n  onClick,\n  children,\n}: {\n  on: boolean;\n  onClick: () => void;\n  children: React.ReactNode;\n}) {\n  return (\n    <button\n      type=\"button\"\n      onClick={onClick}\n      aria-pressed={on}\n      className={`rounded-full px-3.5 py-1.5 text-xs font-semibold ${on ? \"bg-forest-deep text-white\" : \"bg-bg text-ink-soft ring-1 ring-line\"}`}\n    >\n      {children}\n    </button>\n  );\n}\n\n/** ISO time → value for <input type=\"datetime-local\"> in local time */\nconst toLocalInput = (iso: string) => {\n  const d = new Date(iso);\n  const pad = (n: number) => String(n).padStart(2, \"0\");\n  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;\n};\n\nconst clamp = (v: string, min: number, max: number, fallback: number) => {\n  const n = Math.round(Number(v));\n  return Number.isFinite(n) ? Math.min(max, Math.max(min, n)) : fallback;\n};\n\nconst input =\n  \"w-full rounded-2xl bg-bg px-4 py-2.5 text-sm outline-none ring-1 ring-line focus:ring-2 focus:ring-forest disabled:opacity-60\";\nconst primaryBtn =\n  \"flex items-center gap-1.5 rounded-full bg-forest px-5 py-2.5 text-sm font-semibold text-white transition-transform active:scale-[0.98] disabled:opacity-40\";\nconst ghost =\n  \"flex items-center gap-1.5 rounded-full px-4 py-2.5 text-sm font-semibold text-ink ring-1 ring-line disabled:opacity-40\";\n",
 "src/lib/content/circles.test.ts": "import { describe, expect, it } from \"vitest\";\nimport { CIRCLES, circleNames, circlesOf, setCircles } from \"./circles\";\nimport type { ContentItem } from \"./types\";\n\nconst item = (over: Partial<ContentItem> = {}) => ({ id: \"x\", kind: \"reel\", topic: \"erection\", title: \"T\", summary: \"\", minutes: 1, tags: [], body: [], ...over }) as unknown as ContentItem;\n\ndescribe(\"Discover circles shared by the app and the Studio (Step 80)\", () => {\n  it(\"has the 7 circles men tap, in their order\", () => {\n    expect(CIRCLES.map((c) => c.label)).toEqual([\"Last longer\", \"Stronger erections\", \"Satisfy her\", \"Natural mixes\", \"Exercises\", \"Quit porn\", \"Desire and round two\"]);\n  });\n\n  it(\"cards use their action; reels and articles use their circle tags; older ones follow their topic\", () => {\n    expect(circlesOf({ ...item(), action: { challenges: [\"her\", \"last\"] } })).toEqual([\"her\", \"last\"]);\n    expect(circlesOf(item({ tags: [\"mixes\", \"garlic\"] }))).toEqual([\"mixes\"]);\n    expect(circlesOf(item({ topic: \"ejaculation\" }))).toEqual([\"last\"]);\n    expect(circlesOf(item({ topic: \"fertility\" }))).toEqual([]);\n  });\n\n  it(\"picking circles in the Studio sets the tags and the topic behind the scenes, keeping other tags\", () => {\n    const a = setCircles(item({ tags: [\"garlic\", \"hard\"] }), [\"her\", \"desire\"]);\n    expect(a.tags).toEqual([\"garlic\", \"her\", \"desire\"]);\n    expect(a.topic).toBe(\"intimacy\");\n    expect(circleNames(a)).toBe(\"Satisfy her · Desire and round two\");\n  });\n\n  it(\"content that fits no circle keeps fertility or sleep-and-body and shows under For you\", () => {\n    const b = setCircles(item({ tags: [\"hard\"] }), [], \"fertility\");\n    expect(b.tags).toEqual([]);\n    expect(b.topic).toBe(\"fertility\");\n    expect(circlesOf(b)).toEqual([]);\n    expect(circleNames(b)).toBe(\"Fertility\");\n  });\n});\n",
 "src/lib/content/circles.ts": "// The circles at the top of Discover (Last longer, Stronger erections, Satisfy her…), Step 80.\n// One list for the men's app AND the Studio, so what staff pick when uploading is what men tap.\n//\n// Where a piece of content's circles come from:\n//  - \"do this\" cards: their action's challenges (Card maker, built-in cards)\n//  - reels, articles, videos…: plain tags (\"last\", \"hard\"…), set in the Studio editor\n//  - older items with neither: worked out from their topic (erection → Stronger erections, …)\n// Every item still has a topic behind the scenes (search, \"topics I follow\", Community, notification\n// groups use it). It's set automatically from the first circle. Content about fertility or sleep/body\n// that fits no circle keeps one of those two topics and shows under \"For you\" only.\n\nimport type { ChallengeId, ContentItem, TopicId } from \"./types\";\n\nexport const CIRCLES: { id: ChallengeId; label: string }[] = [\n  { id: \"last\", label: \"Last longer\" },\n  { id: \"hard\", label: \"Stronger erections\" },\n  { id: \"her\", label: \"Satisfy her\" },\n  { id: \"mixes\", label: \"Natural mixes\" },\n  { id: \"train\", label: \"Exercises\" },\n  { id: \"reset\", label: \"Quit porn\" },\n  { id: \"desire\", label: \"Desire and round two\" },\n];\nexport const CIRCLE_IDS: ChallengeId[] = CIRCLES.map((c) => c.id);\nexport const CIRCLE_LABEL = Object.fromEntries(CIRCLES.map((c) => [c.id, c.label])) as Record<ChallengeId, string>;\n\n/** Content that fits no circle: shown under \"For you\", found in search and in \"topics I follow\". */\nexport const NO_CIRCLE: { topic: TopicId; label: string }[] = [\n  { topic: \"fertility\", label: \"Fertility\" },\n  { topic: \"wellbeing\", label: \"Sleep and body\" },\n];\n\n/** The topic each circle files content under (behind the scenes). */\nexport const TOPIC_OF_CIRCLE: Record<ChallengeId, TopicId> = {\n  last: \"ejaculation\",\n  hard: \"erection\",\n  her: \"intimacy\",\n  mixes: \"erection\",\n  train: \"erection\",\n  reset: \"confidence\",\n  desire: \"libido\",\n};\n\n/** For older content that has a topic but no circle yet. */\nconst CIRCLE_OF_TOPIC: Partial<Record<TopicId, ChallengeId>> = {\n  erection: \"hard\",\n  ejaculation: \"last\",\n  libido: \"desire\",\n  intimacy: \"her\",\n  confidence: \"reset\",\n};\n\nexport const isCircle = (t: string): t is ChallengeId => (CIRCLE_IDS as string[]).includes(t);\n\n/** The circles a piece of content shows under on Discover. */\nexport function circlesOf(item: Pick<ContentItem, \"tags\" | \"topic\"> & { action?: { challenges: ChallengeId[] } }): ChallengeId[] {\n  if (item.action?.challenges?.length) return item.action.challenges;\n  const fromTags = CIRCLE_IDS.filter((id) => item.tags?.includes(id));\n  if (fromTags.length) return fromTags;\n  const t = CIRCLE_OF_TOPIC[item.topic];\n  return t ? [t] : [];\n}\n\n/** Put content in these circles (Studio editor). No circles = one of the NO_CIRCLE topics. */\nexport function setCircles<T extends ContentItem>(item: T, circles: ChallengeId[], noCircleTopic: TopicId = \"wellbeing\"): T {\n  const tags = [...item.tags.filter((t) => !isCircle(t)), ...circles];\n  const topic = circles.length ? TOPIC_OF_CIRCLE[circles[0]] : NO_CIRCLE.some((n) => n.topic === item.topic) ? item.topic : noCircleTopic;\n  return {\n    ...item,\n    tags,\n    topic,\n    ...(item.action && circles.length ? { action: { ...item.action, challenges: circles } } : {}),\n  };\n}\n\n/** \"Last longer · Satisfy her\", or \"Fertility\" for content outside the circles. */\nexport function circleNames(item: Pick<ContentItem, \"tags\" | \"topic\"> & { action?: { challenges: ChallengeId[] } }): string {\n  const c = circlesOf(item);\n  if (c.length) return c.map((id) => CIRCLE_LABEL[id]).join(\" · \");\n  return NO_CIRCLE.find((n) => n.topic === item.topic)?.label ?? \"For you\";\n}\n"
};
for (const [path, text] of Object.entries(files)) {
  mkdirSync(dirname(path), { recursive: true });
  writeFileSync(path, text);
  console.log("wrote", path);
}
console.log("Step 80 done: " + Object.keys(files).length + " files.");
